	/* SubQuery from Source ==>SQ_SQ_SC_RR_BNK_TO_SERVICE_ACC_MAP_DIM */
/* transType: "Source" */
Select 
MNEMONIC,
ACCOUNT_IDENTIFIER,
EXCHANGE,
SUB_ACCOUNT,
IH_EXCHANGE
 from 
(SELECT
 distinct
    MNEMONIC as MNEMONIC,
    ACCOUNT_IDENTIFIER as ACCOUNT_IDENTIFIER,
    EXCHANGE as EXCHANGE,
