SQ_SC_STG_SWP_VARIATION_MARGINOut as (
	/* SubQuery from Source ==>SQ_SQ_SC_STG_SWP_VARIATION_MARGIN */
/* transType: "Source" */
Select 
CLEARING_MEMBER_LCH_CODE_VM,
SEGREGATED_ACCOUNT_PAR,
LOCAL_VM_CURRENCY,
DEFAULT_FUND_CURRENCY,
SUM_POSITIVE_VM,
SUM_NEGATIVE_VM
 from 
(SELECT
    VM.CLEARING_MEMBER_LCH_CODE as CLEARING_MEMBER_LCH_CODE_VM,
    PAR1.SEGREGATED_ACCOUNT as SEGREGATED_ACCOUNT_PAR,
    VM.CURRENCY_CODE as LOCAL_VM_CURRENCY,
    DEF_CURR.DEFAULT_FUND_CURRENCY as DEFAULT_FUND_CURRENCY,
    SUM(NVL(DECODE(SIGN(VM.NPV_CHANGE_DISPLAY),1,VM.NPV_CHANGE_DISPLAY,0,VM.NPV_CHANGE_DISPLAY,0),0)) as SUM_POSITIVE_VM,
    SUM(NVL(DECODE(SIGN(VM.NPV_CHANGE_DISPLAY),-1,VM.NPV_CHANGE_DISPLAY,0),0)) as SUM_NEGATIVE_VM
 FROM
    STG_SWP_VARIATION_MARGIN as VM
 INNER JOIN 
  BATCH_MASTER as BAT
 ON
  VM.BATCH_ID= BAT.BATCH_ID
 INNER JOIN 
  STG_SWP_PARTY as PAR1
 ON
  PAR1.BATCH_ID= BAT.BATCH_ID AND 
  VM.PARTY_ID= PAR1.PARTY_ID
 WHERE  
   BAT.BATCH_ID =
 (SELECT
    BATCH_ID
 FROM
    BATCH_MASTER
 WHERE  
  BATCH_FEED_INFO= 'SWP_CORE_DATA_LOAD' AND 
  BATCH_BUSINESS_FROM_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND 
  BATCH_TYPE= 'EOD' AND 
  BATCH_STATUS= 'C') AND 
   VM.BATCH_DETAILS_ID IN
 (SELECT
    ID
 FROM
    BATCH_DETAILS
 WHERE  
  BATCH_ID= BAT.BATCH_ID AND 
  FILE_NAME IN('V_EXT_VARIATION_MARGIN_PTFL') AND 
  ACTIVE_FLAG= 1) AND 
  PAR1.STATUS= 'ACTIVE' AND 
  PAR1.ACTIVE_FLAG= 1 AND 
  VM.ACTIVE_FLAG= 1 AND 
  VM.BUSINESS_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD')
 GROUP BY
    VM.CLEARING_MEMBER_LCH_CODE,
    PAR1.SEGREGATED_ACCOUNT,
    VM.CURRENCY_CODE,
    DEF_CURR.DEFAULT_FUND_CURRENCY)
 ),

SQ_SC_STG_SWP_TRADEOut as (
	/* SubQuery from Source ==>SQ_SQ_SC_STG_SWP_TRADE */
/* transType: "Source" */
Select 
BATCH_ID_TRA,
BATCH_DETAILS_ID_TRA,
BUSINESS_DATE_TRA,
TRADE_ID_TRA,
SOURCE_REG_BODY_DISPLAY_TRA,
REGISTERED_BUS_DATE_TRA,
ORIGINATING_EVENT_TRA,
TERMINATING_EVENT_TRA,
TRANSACTION_STATUS_TRA,
CURRENT_STATUS_TRA,
CURRENT_STATUS_BUS_DATE_TRA,
STATUS_REC_DATE_TIME_TRA,
LCH_PRODUCT_TYPE_TRA,
PRODUCT_TYPE_TRA,
CONTRACTUAL_DEFINITIONS_TRA,
CURRENCY_CODE_TRA,
UTI_TRA,
UTI_NAMESPACE,
EXECUTION_VENUE_NAME_TRA,
SOURCE_LCH_CODE_TRA,
INITIAL_NOTIONAL_AMOUNT_TRA,
REGISTERED_DATE_TIME_TRA,
EXECUTION_DATE_TIME_TRA,
TERMINATION_DATE_TRA,
CLEARING_MEMBER_LEI_PAR,
CLEARING_MEMBER_LCH_CODE_PAR,
SEGREGATED_ACCOUNT_PAR,
EFFECTIVE_DATE_TRA,
NPV_VAL,
CURRENCY_CODE_VAL,
BUSINESS_DATE_VAL,
LEG_TYPE_PAY,
INITIAL_NOTIONAL_AMOUNT_PAY,
INITIAL_SPREAD_PAY,
FIXED_FLOAT_TYPE_PAY,
FIXED_RATE_DISPLAY_PAY,
DAY_COUNT_FRACTION_PAY,
PAY_PERIOD_PAY,
PAY_PERIOD_MPLIER_PAY,
RESET_PERIOD_PAY,
RESET_PERIOD_MPLIER_PAY,
LEG_TYPE_REC,
INITIAL_SPREAD_REC,
FIXED_FLOAT_TYPE_REC,
FIXED_RATE_DISPLAY_REC,
DAY_COUNT_FRACTION_REC,
PAY_PERIOD_REC,
PAY_PERIOD_MPLIER_REC,
RESET_PERIOD_REC,
RESET_PERIOD_MPLIER_REC,
INDEX_FULL_NAME_PTEN,
PERIOD_CODE_PTEN,
PERIOD_MULTIPLIER_PTEN,
INDEX_FULL_NAME_RTEN,
PERIOD_CODE_RTEN,
PERIOD_MULTIPLIER_RTEN,
VNS_SCHEDULE_ID_VNS,
TRADE_DETAILS_ID_VNS,
CURRENCY_CODE_VNS,
CURRENT_SCHEDULE_NOTIONAL_VNS,
STEP_DATE_FROM_VNS,
STEP_DATE_TO_VNS,
LAST_SCHEDULE_NOTIONAL_VNS,
LAST_SCHEDULE_DATE_VNS,
STRING_VALUE_AV,
CURRENT_STATUS_DATE_TIME_TRA,
EXECUTION_SOURCE_NAME_TRA,
EXECUTION_VENUE_TYPE_TRA,
PRIOR_UTI,
PRIOR_UTI_NAMESPACE,
PERIOD_NAME_DISPLAY_PAY,
PERIOD_NAME_DISPLAY_REC,
INDEX_NAME_ISDA2021_PAY,
INDEX_NAME_ISDA2021_REC,
CFI_VNS_ATTR_4,
CURRENCY_CODE_SETTLEMENT,
BOND_ISIN,
EXECUTION_VENUE_LEI,
INITIAL_NOTIONAL_AMOUNT_REC
 from 
(WITH 
 BI as (
 SELECT
 distinct
    BATCH_ID,
    BATCH_START_DATE,
    BATCH_BUSINESS_FROM_DATE
 FROM
    BATCH_MASTER as T1
 WHERE  
  T1.BATCH_TYPE= 'EOD' AND 
  T1.BATCH_STATUS= 'C' AND 
  T1.BATCH_FEED_INFO= 'SWP_CORE_DATA_LOAD' AND 
   T1.BATCH_BUSINESS_FROM_DATE =
 (SELECT
    BATCH_BUSINESS_FROM_DATE
 FROM
{{ source('DW_MART', 'BATCH_MASTER') }}
 WHERE  
  BATCH_FEED_INFO= 'EMIR_SWC_TR_LOAD' AND 
  BATCH_STATUS= 'I')),
 VNS as (
 SELECT
    BUSINESS_DATE as BUSINESS_DATE_VNS,
    VNS_SCHEDULE_ID as VNS_SCHEDULE_ID_VNS,
    TRADE_DETAILS_ID as TRADE_DETAILS_ID_VNS,
    CURRENCY_CODE as CURRENCY_CODE_VNS,
    CURRENT_SCHEDULE_NOTIONAL as CURRENT_SCHEDULE_NOTIONAL_VNS,
    STEP_DATE_FROM as STEP_DATE_FROM_VNS,
    STEP_DATE_TO as STEP_DATE_TO_VNS,
    LAST_SCHEDULE_NOTIONAL as LAST_SCHEDULE_NOTIONAL_VNS,
    LAST_SCHEDULE_DATE as LAST_SCHEDULE_DATE_VNS
 FROM(
 SELECT
    BUSINESS_DATE,
    VNS_SCHEDULE_ID,
    TRADE_DETAILS_ID,
    CURRENCY_CODE,
    ABS(NOTIONAL_AMOUNT) as CURRENT_SCHEDULE_NOTIONAL,
    UNADJUSTED_EFFECTIVE_DATE as STEP_DATE_FROM,
    LEAD(UNADJUSTED_EFFECTIVE_DATE -1) OVER(PARTITION BY BUSINESS_DATE,TRADE_DETAILS_ID,CURRENCY_CODE ORDER BY BUSINESS_DATE,TRADE_DETAILS_ID,CURRENCY_CODE,UNADJUSTED_EFFECTIVE_DATE ASC) as STEP_DATE_TO,
    FIRST_VALUE(ABS(NOTIONAL_AMOUNT)) OVER(PARTITION BY BUSINESS_DATE,TRADE_DETAILS_ID,CURRENCY_CODE ORDER BY BUSINESS_DATE,TRADE_DETAILS_ID,CURRENCY_CODE,UNADJUSTED_EFFECTIVE_DATE DESC) as LAST_SCHEDULE_NOTIONAL,
    FIRST_VALUE(UNADJUSTED_EFFECTIVE_DATE) OVER(PARTITION BY BUSINESS_DATE,TRADE_DETAILS_ID,CURRENCY_CODE ORDER BY BUSINESS_DATE,TRADE_DETAILS_ID,CURRENCY_CODE,UNADJUSTED_EFFECTIVE_DATE DESC) as LAST_SCHEDULE_DATE
 FROM
    STG_SWP_VARIABLE_NOTIONAL_SCHL as T3
 WHERE  
   T3.BUSINESS_DATE =
 (SELECT
    BATCH_BUSINESS_FROM_DATE
 FROM
    BI) AND 
   T3.BATCH_ID =
 (SELECT
    BATCH_ID
 FROM
    BI) AND 
  T3.ACTIVE_FLAG= 1)
 WHERE  
  STEP_DATE_FROM <= BUSINESS_DATE AND 
  NVL(STEP_DATE_TO,TO_DATE('31-DEC-2999','DD-MON-YYYY')) >= BUSINESS_DATE),
 STG_SWP_INDX_TENR as (
 SELECT
    REC.TRADE_DETAILS_ID,
    REC.DAY_COUNT_FRACTION,
    REC.FIXED_FLOAT_TYPE,
    REC.FIXED_RATE_DISPLAY,
    REC.INITIAL_SPREAD,
    REC.LEG_TYPE,
    REC.INITIAL_NOTIONAL_AMOUNT,
    REC.PAY_PERIOD,
    REC.PAY_PERIOD_MPLIER,
    REC.RESET_PERIOD,
    REC.RESET_PERIOD_MPLIER,
    T1.INDEX_FULL_NAME,
    T1.PERIOD_CODE,
    T1.PERIOD_MULTIPLIER,
    REC.PAY_RECEIVE_TYPE,
    REC.BUSINESS_DATE,
    REC.TRADE_ID,
    T1.PERIOD_NAME_DISPLAY,
    T1.INDEX_NAME_ISDA2021,
    REC.UNADJUSTED_EFFECTIVE_DATE,
    REC.UNADJUSTED_TERMINATION_DATE
 FROM
    STG_SWP_TRADE_DETAILS as REC
 JOIN
  BI
 ON
  BI.BATCH_BUSINESS_FROM_DATE= REC.BUSINESS_DATE
 LEFT JOIN 
 (SELECT
    *
 FROM
    STG_SWP_INDEX_TENOR
 WHERE 
   BUSINESS_DATE =
 (SELECT
    BATCH_BUSINESS_FROM_DATE
 FROM
    BI)) T1
 ON
  T1.BUSINESS_DATE= REC.BUSINESS_DATE AND 
  REC.BUSINESS_DATE= BI.BATCH_BUSINESS_FROM_DATE AND 
  REC.BATCH_ID= BI.BATCH_ID AND 
  T1.BATCH_ID= REC.BATCH_ID AND 
  REC.ACTIVE_FLAG= 1 AND 
  T1.ACTIVE_FLAG= 1 AND 
  T1.INDEX_TENOR_ID= REC.INDEX_TENOR_ID AND 
  T1.BUSINESS_DATE= BI.BATCH_BUSINESS_FROM_DATE
 WHERE  
  REC.BUSINESS_DATE= BI.BATCH_BUSINESS_FROM_DATE AND 
  REC.BATCH_ID= BI.BATCH_ID AND 
  REC.ACTIVE_FLAG= 1),
 TRADE as (
 SELECT
    T1.PARTY_ID,
    T1.BATCH_ID,
    T1.BATCH_DETAILS_ID,
    T1.CURRENCY_CODE,
    T1.CONTRACTUAL_DEFINITIONS,
    T1.CURRENT_STATUS,
    T1.CURRENT_STATUS_BUS_DATE,
    T1.EXECUTION_DATE_TIME,
    T1.EXECUTION_VENUE_NAME,
    T1.INITIAL_NOTIONAL_AMOUNT,
    T1.LCH_PRODUCT_TYPE,
    T1.PRODUCT_TYPE,
    T1.REGISTERED_BUS_DATE,
    T1.REGISTERED_DATE_TIME,
    T1.SOURCE_LCH_CODE,
    T1.STATUS_REC_DATE_TIME,
    T1.ORIGINATING_EVENT,
    T1.TERMINATING_EVENT,
    T1.TERMINATION_DATE,
    T1.TRADE_ID,
    T1.SOURCE_REG_BODY_DISPLAY,
    T1.TRANSACTION_STATUS,
    T1.UTI,
    T1.UTI_NAMESPACE,
    T1.BUSINESS_DATE,
    T1.EFFECTIVE_DATE,
    T1.CURRENT_STATUS_DATE_TIME,
    T1.EXECUTION_SOURCE_NAME,
    T1.EXECUTION_VENUE_TYPE,
    T1.PRIOR_UTI,
    T1.PRIOR_UTI_NAMESPACE,
    T1.CURRENCY_CODE_SETTLEMENT,
    T1.BOND_ISIN,
    T1.EXECUTION_VENUE_LEI
 FROM
    STG_SWP_TRADE as T1
 INNER JOIN 
  STG_SWP_REGULATOR_CONTROL as SS
 ON
  T1.TRADE_ID= SS.SRS_RECORD_ID AND 
  T1.BUSINESS_DATE= SS.BUSINESS_DATE AND 
  SS.ACTIVE_FLAG= 1
 WHERE  
   SS.BUSINESS_DATE =
 (SELECT
    BATCH_BUSINESS_FROM_DATE
 FROM
    BI) AND 
   SS.BATCH_ID =
 (SELECT
    BATCH_ID
 FROM
    BI) AND 
  SS.ACTIVE_FLAG= 1 AND 
   T1.BUSINESS_DATE =
 (SELECT
    BATCH_BUSINESS_FROM_DATE
 FROM
    BI) AND 
   T1.BATCH_ID =
 (SELECT
    BATCH_ID
 FROM
    BI) AND 
  T1.ACTIVE_FLAG= 1 AND 
  SS.SRS_RECORD_TYPE= 'TRADE_ID' AND 
  SS.REGULATOR_NAME= 'UNAVISTA' AND 
   UPPER(T1.CURRENT_STATUS) NOT IN
 (SELECT
    UPPER(STRING_VALUE2)
 FROM
    APPLICATION_VARIABLES
 WHERE 
  VARIABLE_NAME= 'EMIR_FILTER_UNREGISTERED_TRADES')),
 CFI as (
 SELECT
    TRADE_ID,
    MAX(diff),
    MIN(diff),
    SIGN(MAX(diff)),
    SIGN(MIN(diff)),
    CASE
 when SIGN(MAX(x.diff)) = 0 AND SIGN(MIN(x.diff)) = 0 
    then
    'C' when SIGN(MAX(x.diff)) = 1 AND SIGN(MIN(x.diff)) = 0 
    then
    'D' when SIGN(MAX(x.diff)) = 0 AND SIGN(MIN(x.diff)) = -1 
    then
    'I' when SIGN(MAX(x.diff)) = 1 AND SIGN(MIN(x.diff)) = -1 
    then
    'Y' END as CFI_VNS_ATTR_4
 FROM
 (SELECT
    td.trade_id,
    NVL(ABS(NVL(LAG(V.NOTIONAL_AMOUNT) OVER(PARTITION BY v.trade_details_id ORDER BY V.UNADJUSTED_EFFECTIVE_DATE ASC),ABS(V.NOTIONAL_AMOUNT))) - ABS(V.NOTIONAL_AMOUNT),0) as DIFF
 FROM
{{ source('reg_rep', 'stg_swp_trade_details') }} as td
 INNER JOIN 
  reg_rep.STG_SWP_VARIABLE_NOTIONAL_SCHL as v
 ON
  V.TRADE_DETAILS_ID= TD.TRADE_DETAILS_ID AND 
  V.BUSINESS_DATE= TD.BUSINESS_DATE AND 
  V.ACTIVE_FLAG= 1
 WHERE  
   td.BUSINESS_DATE =
 (SELECT
    BATCH_BUSINESS_FROM_DATE
 FROM
    BI) AND 
   td.BATCH_ID =
 (SELECT
    BATCH_ID
 FROM
    BI) AND 
  TD.ACTIVE_FLAG= 1 AND 
   v.BUSINESS_DATE =
 (SELECT
    BATCH_BUSINESS_FROM_DATE
 FROM
    BI) AND 
   v.BATCH_ID =
 (SELECT
    BATCH_ID
 FROM
    BI) AND 
  V.ACTIVE_FLAG= 1) x
 GROUP BY
    TRADE_ID)
 
 SELECT
    TRA.BATCH_ID as BATCH_ID_TRA,
    TRA.BATCH_DETAILS_ID as BATCH_DETAILS_ID_TRA,
    TRA.BUSINESS_DATE as BUSINESS_DATE_TRA,
    TRA.TRADE_ID as TRADE_ID_TRA,
    TRA.SOURCE_REG_BODY_DISPLAY as SOURCE_REG_BODY_DISPLAY_TRA,
    TRA.REGISTERED_BUS_DATE as REGISTERED_BUS_DATE_TRA,
    TRA.ORIGINATING_EVENT as ORIGINATING_EVENT_TRA,
    TRA.TERMINATING_EVENT as TERMINATING_EVENT_TRA,
    TRA.TRANSACTION_STATUS as TRANSACTION_STATUS_TRA,
    TRA.CURRENT_STATUS as CURRENT_STATUS_TRA,
    TRA.CURRENT_STATUS_BUS_DATE as CURRENT_STATUS_BUS_DATE_TRA,
    TRA.STATUS_REC_DATE_TIME as STATUS_REC_DATE_TIME_TRA,
    TRA.LCH_PRODUCT_TYPE as LCH_PRODUCT_TYPE_TRA,
    TRA.PRODUCT_TYPE as PRODUCT_TYPE_TRA,
    TRA.CONTRACTUAL_DEFINITIONS as CONTRACTUAL_DEFINITIONS_TRA,
    TRA.CURRENCY_CODE as CURRENCY_CODE_TRA,
    TRA.UTI as UTI_TRA,
    TRA.UTI_NAMESPACE as UTI_NAMESPACE_TRA,
    TRA.EXECUTION_VENUE_NAME as EXECUTION_VENUE_NAME_TRA,
    TRA.SOURCE_LCH_CODE as SOURCE_LCH_CODE_TRA,
    TRA.INITIAL_NOTIONAL_AMOUNT as INITIAL_NOTIONAL_AMOUNT_TRA,
    TRA.REGISTERED_DATE_TIME as REGISTERED_DATE_TIME_TRA,
    TRA.EXECUTION_DATE_TIME as EXECUTION_DATE_TIME_TRA,
    NVL(PAY.UNADJUSTED_TERMINATION_DATE,REC.UNADJUSTED_TERMINATION_DATE) as TERMINATION_DATE,
    PAR.CLEARING_MEMBER_LEI as CLEARING_MEMBER_LEI_PAR,
    PAR.CLEARING_MEMBER_LCH_CODE as CLEARING_MEMBER_LCH_CODE_PAR,
    PAR.SEGREGATED_ACCOUNT as SEGREGATED_ACCOUNT_PAR,
    NVL(PAY.UNADJUSTED_EFFECTIVE_DATE,REC.UNADJUSTED_EFFECTIVE_DATE) as EFFECTIVE_DATE,
    VAL.NPV as NPV_VAL,
    VAL.CURRENCY_CODE as CURRENCY_CODE_VAL,
    VAL.BUSINESS_DATE as BUSINESS_DATE_VAL,
    PAY.LEG_TYPE as LEG_TYPE_PAY,
    PAY.INITIAL_NOTIONAL_AMOUNT as INITIAL_NOTIONAL_AMOUNT_PAY,
    PAY.INITIAL_SPREAD as INITIAL_SPREAD_PAY,
    PAY.FIXED_FLOAT_TYPE as FIXED_FLOAT_TYPE_PAY,
    PAY.FIXED_RATE_DISPLAY as FIXED_RATE_DISPLAY_PAY,
    PAY.DAY_COUNT_FRACTION as DAY_COUNT_FRACTION_PAY,
    PAY.PAY_PERIOD as PAY_PERIOD_PAY,
    PAY.PAY_PERIOD_MPLIER as PAY_PERIOD_MPLIER_PAY,
    PAY.RESET_PERIOD as RESET_PERIOD_PAY,
    PAY.RESET_PERIOD_MPLIER as RESET_PERIOD_MPLIER_PAY,
    REC.LEG_TYPE as LEG_TYPE_REC,
    REC.INITIAL_SPREAD as INITIAL_SPREAD_REC,
    REC.FIXED_FLOAT_TYPE as FIXED_FLOAT_TYPE_REC,
    REC.FIXED_RATE_DISPLAY as FIXED_RATE_DISPLAY_REC,
    REC.DAY_COUNT_FRACTION as DAY_COUNT_FRACTION_REC,
    REC.PAY_PERIOD as PAY_PERIOD_REC,
    REC.PAY_PERIOD_MPLIER as PAY_PERIOD_MPLIER_REC,
    REC.RESET_PERIOD as RESET_PERIOD_REC,
    REC.RESET_PERIOD_MPLIER as RESET_PERIOD_MPLIER_REC,
    PAY.INDEX_FULL_NAME as INDEX_FULL_NAME_PTEN,
    PAY.PERIOD_CODE as PERIOD_CODE_PTEN,
    PAY.PERIOD_MULTIPLIER as PERIOD_MULTIPLIER_PTEN,
    REC.INDEX_FULL_NAME as INDEX_FULL_NAME_RTEN,
    REC.PERIOD_CODE as PERIOD_CODE_RTEN,
    REC.PERIOD_MULTIPLIER as PERIOD_MULTIPLIER_RTEN,
    VNS.VNS_SCHEDULE_ID_VNS as VNS_SCHEDULE_ID_VNS,
    VNS.TRADE_DETAILS_ID_VNS as TRADE_DETAILS_ID_VNS,
    VNS.CURRENCY_CODE_VNS as CURRENCY_CODE_VNS,
    VNS.CURRENT_SCHEDULE_NOTIONAL_VNS as CURRENT_SCHEDULE_NOTIONAL_VNS,
    VNS.STEP_DATE_FROM_VNS as STEP_DATE_FROM_VNS,
    VNS.STEP_DATE_TO_VNS as STEP_DATE_TO_VNS,
    VNS.LAST_SCHEDULE_NOTIONAL_VNS as LAST_SCHEDULE_NOTIONAL_VNS,
    VNS.LAST_SCHEDULE_DATE_VNS as LAST_SCHEDULE_DATE_VNS,
    AV.STRING_VALUE as STRING_VALUE_AV,
    TRA.CURRENT_STATUS_DATE_TIME as CURRENT_STATUS_DATE_TIME_TRA,
    TRA.EXECUTION_SOURCE_NAME as EXECUTION_SOURCE_NAME_TRA,
    TRA.EXECUTION_VENUE_TYPE as EXECUTION_VENUE_TYPE_TRA,
    TRA.PRIOR_UTI as PRIOR_UTI,
    TRA.PRIOR_UTI_NAMESPACE as PRIOR_UTI_NAMESPACE,
    PAY.PERIOD_NAME_DISPLAY as PERIOD_NAME_DISPLAY_PAY,
    REC.PERIOD_NAME_DISPLAY as PERIOD_NAME_DISPLAY_REC,
    PAY.INDEX_NAME_ISDA2021 as INDEX_NAME_ISDA2021_PAY,
    REC.INDEX_NAME_ISDA2021 as INDEX_NAME_ISDA2021_REC,
    CFI.CFI_VNS_ATTR_4 as CFI_VNS_ATTR_4,
    TRA.CURRENCY_CODE_SETTLEMENT as CURRENCY_CODE_SETTLEMENT,
    TRA.BOND_ISIN as BOND_ISIN,
    TRA.EXECUTION_VENUE_LEI as EXECUTION_VENUE_LEI,
    REC.INITIAL_NOTIONAL_AMOUNT as INITIAL_NOTIONAL_AMOUNT_REC
 FROM
    TRADE as TRA
 INNER JOIN 
  STG_SWP_INDX_TENR as PAY
 ON
  TRA.TRADE_ID= PAY.TRADE_ID AND 
  TRA.BUSINESS_DATE= PAY.BUSINESS_DATE AND 
  PAY.PAY_RECEIVE_TYPE= 'R'
 LEFT JOIN 
  VNS
 ON
  PAY.TRADE_DETAILS_ID= VNS.TRADE_DETAILS_ID_VNS
 INNER JOIN 
  STG_SWP_INDX_TENR as REC
 ON
  TRA.TRADE_ID= REC.TRADE_ID AND 
  TRA.BUSINESS_DATE= REC.BUSINESS_DATE AND 
  REC.PAY_RECEIVE_TYPE= 'P'
 LEFT OUTER JOIN 
  STG_SWP_TRADE_VALUATIONS as VAL
 ON
  TRA.TRADE_ID= VAL.TRADE_ID AND 
  VAL.BUSINESS_DATE= TRA.BUSINESS_DATE AND 
  VAL.ACTIVE_FLAG= 1 AND 
  VAL.BATCH_ID= TRA.BATCH_ID
 INNER JOIN 
  STG_SWP_PARTY as PAR
 ON
  PAR.BUSINESS_DATE= TRA.BUSINESS_DATE AND 
  PAR.BATCH_ID= TRA.BATCH_ID AND 
  PAR.ACTIVE_FLAG= 1 AND 
  TRA.PARTY_ID= PAR.PARTY_ID
 LEFT JOIN 
  APPLICATION_VARIABLES as AV
 ON
  (UPPER(TRA.TRANSACTION_STATUS)= UPPER(AV.STRING_VALUE2)) AND 
  AV.VARIABLE_NAME= 'EMIR_SWP_ACTION_TYPE' AND 
  DECODE(UPPER(STRING_VALUE3),'*',UPPER(TRA.CURRENT_STATUS),UPPER(STRING_VALUE3))= UPPER(TRA.CURRENT_STATUS) AND 
  DECODE(UPPER(STRING_VALUE4),'*',UPPER(TRA.ORIGINATING_EVENT),UPPER(STRING_VALUE4))= UPPER(TRA.ORIGINATING_EVENT) AND 
  UPPER(STRING_VALUE5)= UPPER(NVL(TRA.TERMINATING_EVENT,'-2'))
 LEFT JOIN 
  CFI
 ON
  CFI.TRADE_ID= TRA.TRADE_ID)
 ),

COUNTERPARTIES_DIMOut as (
	/* transType: "LookupSource" */
Select ID, 
