exp_VM_LOCAL_TO_DEF_CURRENCYOut as (
	/* transType: "Expression" */
Select 
	CLEARING_MEMBER_LCH_CODE_VM as CLEARING_MEMBER_LCH_CODE_VM,
	 SEGREGATED_ACCOUNT_PAR as SEGREGATED_ACCOUNT_PAR,
	 LOCAL_VM_CURRENCY as LOCAL_VM_CURRENCY,
	 DEFAULT_FUND_CURRENCY as DEFAULT_FUND_CURRENCY,
	 SUM_POSITIVE_VM as SUM_POSITIVE_VM,
	 SUM_NEGATIVE_VM as SUM_NEGATIVE_VM,
	 'EOD' as v_TYPE,
	 TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ) as v_BUSINESS_DATE,
	 dsf_1.FX_RATE as v_FX_RATE,
	 SUM_POSITIVE_VM * v_FX_RATE as o_SUM_POSITIVE_VM_DEF,
	 SUM_NEGATIVE_VM * v_FX_RATE as o_SUM_NEGATIVE_VM_DEF,
	 'SWP' as o_EXCHANGE
From SQ_SC_STG_SWP_VARIATION_MARGINOut as SQ_SC_STG_SWP_VARIATION_MARGINOut
LEFT JOIN (
SELECT FX_RATE, TYPE, SOURCE_CURRENCY, TARGET_CURRENCY, BUSINESS_DATE_TIME FROM (  SELECT FX_RATE, TYPE, SOURCE_CURRENCY, TARGET_CURRENCY, BUSINESS_DATE_TIME,  ROW_NUMBER() OVER (PARTITION BY TYPE, SOURCE_CURRENCY, TARGET_CURRENCY, BUSINESS_DATE_TIME ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT FX_RATE, TYPE, SOURCE_CURRENCY, TARGET_CURRENCY, BUSINESS_DATE_TIME,  ROW_NUMBER() OVER (PARTITION BY TYPE, SOURCE_CURRENCY, TARGET_CURRENCY, BUSINESS_DATE_TIME ORDER BY TYPE, SOURCE_CURRENCY, TARGET_CURRENCY, BUSINESS_DATE_TIME NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    FX_RATE_DIM )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.TYPE = v_TYPE AND dsf_1.SOURCE_CURRENCY = LOCAL_VM_CURRENCY AND dsf_1.TARGET_CURRENCY = DEFAULT_FUND_CURRENCY AND dsf_1.BUSINESS_DATE_TIME = v_BUSINESS_DATE
),

