agg_SUM_VM_Out as (
	/* transType: "Aggregator" */
 
 select 
	CLEARING_MEMBER_LCH_CODE_VM as CLEARING_MEMBER_LCH_CODE_VM,
	 SEGREGATED_ACCOUNT_PAR as SEGREGATED_ACCOUNT_PAR,
	 DEFAULT_FUND_CURRENCY as DEFAULT_FUND_CURRENCY,
	 SUM ( o_SUM_POSITIVE_VM_DEF ) as o_SUM_CONV_POSITIVE_VM,
	 SUM ( o_SUM_NEGATIVE_VM_DEF ) as o_SUM_CONV_NEGATIVE_VM
 from exp_VM_LOCAL_TO_DEF_CURRENCYOut
 group by CLEARING_MEMBER_LCH_CODE_VM, SEGREGATED_ACCOUNT_PAR, DEFAULT_FUND_CURRENCY
),
agg_SUM_VM_NonGroupBy as (
 select 
  	CLEARING_MEMBER_LCH_CODE_VM,
	 SEGREGATED_ACCOUNT_PAR,
	 DEFAULT_FUND_CURRENCY,
	 o_SUM_POSITIVE_VM_DEF,
	 o_SUM_NEGATIVE_VM_DEF,
	 o_EXCHANGE
 from (
  select 
   	CLEARING_MEMBER_LCH_CODE_VM,
	 SEGREGATED_ACCOUNT_PAR,
	 DEFAULT_FUND_CURRENCY,
	 o_SUM_POSITIVE_VM_DEF,
	 o_SUM_NEGATIVE_VM_DEF,
	 o_EXCHANGE,
   ROW_NUMBER() OVER (
    PARTITION BY CLEARING_MEMBER_LCH_CODE_VM, SEGREGATED_ACCOUNT_PAR, DEFAULT_FUND_CURRENCY
    ORDER BY CLEARING_MEMBER_LCH_CODE_VM, SEGREGATED_ACCOUNT_PAR, DEFAULT_FUND_CURRENCY
   ) as rnk_lst
  from exp_VM_LOCAL_TO_DEF_CURRENCYOut
 ) t
 where rnk_lst = 1
),
agg_SUM_VMOut as (
 select 
	dsf_1.CLEARING_MEMBER_LCH_CODE_VM,
	 dsf_1.SEGREGATED_ACCOUNT_PAR,
	 dsf_1.DEFAULT_FUND_CURRENCY,
	 dsf_1.o_SUM_CONV_POSITIVE_VM,
	 dsf_1.o_SUM_CONV_NEGATIVE_VM,
	 dsf_2.o_SUM_POSITIVE_VM_DEF,
	 dsf_2.o_SUM_NEGATIVE_VM_DEF,
	 dsf_2.o_EXCHANGE
 from agg_SUM_VM_Out dsf_1
 inner join agg_SUM_VM_NonGroupBy dsf_2 on dsf_1.CLEARING_MEMBER_LCH_CODE_VM = dsf_2.CLEARING_MEMBER_LCH_CODE_VM AND dsf_1.SEGREGATED_ACCOUNT_PAR = dsf_2.SEGREGATED_ACCOUNT_PAR AND dsf_1.DEFAULT_FUND_CURRENCY = dsf_2.DEFAULT_FUND_CURRENCY
)
),

