LKP_ENTITY_DIMOut as (
	/* transType: "Lookup Procedure" */
Select 
	ID as ID,
	 LEGAL_ENTITY_IDENTIFIER as LEGAL_ENTITY_IDENTIFIER,
	 JNR_TRADE_CALYPSO_DATAOut.in_ENTITY as in_ENTITY_1,
	 JNR_TRADE_CALYPSO_DATA.O_ENTITY AS in_ENTITY_2 
FROM
	JNR_TRADE_CALYPSO_DATAOut as JNR_TRADE_CALYPSO_DATAOut 
 LEFT JOIN  ( select * from (
select 
*,NAME,row_number() over(partition by NAME order by rnk_fst desc nulls last) as rnk_lst
from
(
select *,NAME,row_number() over(partition by NAME order by NAME nulls last) as rnk_fst
from ( SELECT
       ENTITY_DIM.ID as ID,
       NVL(ENTITY_DIM.LEGAL_ENTITY_IDENTIFIER,ENTITY_DIM.CFTC_INTERIM_COMPLIANT_ID) as LEGAL_ENTITY_IDENTIFIER,
       ENTITY_DIM.NAME as NAME
 FROM
       ENTITY_DIM
 WHERE   
   TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') >= EFFECTIVE_DATE AND  
   TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') <= NVL(EXPIRATION_DATE,TO_DATE('31-DEC-2099','DD-MON-YYYY')) )
) lkp_inner
) lkp_outer
where rnk_lst=1 ) 
ON
	NAME = in_ENTITY
 
),

