	 LAST_SCHEDULE_DATE_VNS as LAST_SCHEDULE_DATE_VNS,
	 O_ACTION_TYPE_APP_VAR as O_ACTION_TYPE_APP_VAR,
	 CLEARING_MEMBER_LCH_CODE_VM as CLEARING_MEMBER_LCH_CODE_VM,
	 SEGREGATED_ACCOUNT_PAR_VM as SEGREGATED_ACCOUNT_PAR_VM,
	 DEFAULT_FUND_CURRENCY as DEFAULT_FUND_CURRENCY,
