	 SUB_ACCOUNT_CAL as SUB_ACCOUNT_CAL,
	 IH_EXCHANGE_CAL as IH_EXCHANGE_CAL,
	 CURRENT_STATUS_DATE_TIME_TRA as CURRENT_STATUS_DATE_TIME_TRA,
	 o_COLLATERAL_PORTFOLIO_ACCOUNT as o_COLLATERAL_PORTFOLIO_ACCOUNT,
	 o_ENTITY_ID as o_ENTITY_ID,
	 TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ) as o_BUSINESS_DATE,
	 O_REPORTING_COUNTERPARTY_ID as O_REPORTING_COUNTERPARTY_ID,
	 ( CASE WHEN UPPER ( TRANSACTION_STATUS_TRA ) = 'DEAD' AND REGISTERED_BUS_DATE_TRA >= TO_TIMESTAMP ( '{{ var("BATCH_BUSINESS_DATE") }}' || ' 00:00:00',
	 'YYYYMMDD HH24:MI:SS' ) THEN 'Y' ELSE 'N' END ) as V_ACTION_TYPE_Z_C_DEAD_FLG,
	 ( CASE WHEN '{{ var("EMIR_TR_EXTRACTION_MODE") }}' = 'DMP' THEN 'Y' ELSE V_ACTION_TYPE_Z_C_DEAD_FLG END ) as O_ACTION_TYPE_Z_C_DEAD_FLG,
	 ( CASE WHEN '{{ var("EMIR_TR_EXTRACTION_MODE") }}' = 'ERROR' THEN 'E' ELSE ( CASE WHEN O_ACTION_TYPE_APP_VAR IS NOT NULL AND CURRENT_STATUS_BUS_DATE_TRA >= TO_TIMESTAMP ( '{{ var("BATCH_BUSINESS_DATE") }}' || ' 00:00:00',
	 'YYYYMMDD HH24:MI:SS' ) THEN ( CASE WHEN O_ACTION_TYPE_APP_VAR = '-' THEN O_ACTION_TYPE_APP_VAR ELSE ( CASE WHEN O_ACTION_TYPE_APP_VAR = '99' THEN ( CASE WHEN V_ACTION_TYPE_Z_C_DEAD_FLG = 'Y' AND UPPER ( CURRENT_STATUS_TRA ) = 'DELETED' AND UPPER ( TERMINATING_EVENT_TRA ) = 'EMIRACCMIGRATION' THEN 'N' ELSE '-' END ) ELSE O_ACTION_TYPE_APP_VAR END ) END ) ELSE ( CASE WHEN UPPER ( TRANSACTION_STATUS_TRA ) = 'LIVE' AND UPPER ( LCH_PRODUCT_TYPE_TRA ) = 'VNS' AND STEP_DATE_FROM_VNS = TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ) THEN 'M' ELSE ( CASE WHEN UPPER ( TRANSACTION_STATUS_TRA ) = 'LIVE' AND CURRENT_STATUS_BUS_DATE_TRA < TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ) THEN 'V' ELSE null END ) END ) END ) END ) as v_ACTION_TYPE_FINAL,
	 v_ACTION_TYPE_FINAL as O_ACTION_TYPE_FINAL,
	 ( CASE WHEN IN ( v_ACTION_TYPE_FINAL,
	 'N',
	 'E' ) = 1 THEN 1 ELSE ( CASE WHEN IN ( v_ACTION_TYPE_FINAL,
	 'M',
	 'V',
	 'R' ) = 1 THEN 2 ELSE ( CASE WHEN IN ( v_ACTION_TYPE_FINAL,
	 'C',
	 'Z' ) = 1 THEN 3 ELSE 9 END ) END ) END ) as O_SORT_ORDER,
	 EXECUTION_SOURCE_NAME_TRA as EXECUTION_SOURCE_NAME_TRA,
	 EXECUTION_VENUE_TYPE_TRA as EXECUTION_VENUE_TYPE_TRA,
	 PRIOR_UTI as PRIOR_UTI,
	 PRIOR_UTI_NAMESPACE as PRIOR_UTI_NAMESPACE,
	 SRC_UTI_TRA as SRC_UTI_TRA,
	 DECODE ( TRUE,
	 V_ROWCOUNT > 99999,
	 2,
	 V_ROWCOUNT + 1 ) as V_ROWCOUNT,
	 DECODE ( TRUE,
	 V_ROWCOUNT > 99999,
	 V_FILECOUNT + 1,
	 V_FILECOUNT ) as V_FILECOUNT,
	 TO_VARCHAR ( CURRENT_TIMESTAMP ( ),
	 'YYYYMMDDHH24MISS' ) as V_FILE_SYSDATETIME,
	 '{{ var("ENTITY") }}' || '_' || '{{ var("SERVICE") }}' || '_TRADES_' || '{{ var("BATCH_BUSINESS_DATE") }}' || '_' || V_FILE_SYSDATETIME || '_' || TO_VARCHAR ( V_FILECOUNT + 1 ) || '.dat' as FileName,
	 PERIOD_NAME_DISPLAY_PAY as PERIOD_NAME_DISPLAY_PAY,
	 PERIOD_NAME_DISPLAY_REC as PERIOD_NAME_DISPLAY_REC,
	 CFI_VNS_ATTR_4 as CFI_VNS_ATTR_4,
	 CURRENCY_CODE_SETTLEMENT as CURRENCY_CODE_SETTLEMENT,
	 BOND_ISIN as BOND_ISIN,
	 INITIAL_NOTIONAL_AMOUNT_REC as INITIAL_NOTIONAL_AMOUNT_REC,
	 INDEX_NAME_ISDA2021_PAY as INDEX_NAME_ISDA2021_PAY,
	 INDEX_NAME_ISDA2021_REC as INDEX_NAME_ISDA2021_REC,
	 CONTRACTUAL_DEFINITIONS_TRA as CONTRACTUAL_DEFINITIONS_TRA,
	 EXECUTION_VENUE_LEI as EXECUTION_VENUE_LEI
From dsJoiner_exp_TRADE_VM0Out as dsJoiner_exp_TRADE_VM0Out),

