DSR_EXP_SPL_EXTRACT_DATAOut as (
	/* transType: "Expression" */
Select 
	UnionOut2.SRC_UTI_TRA as SRC_UTI_TRA,
	 UnionOut2.UTI_TRA1 as UTI_TRA
From UnionOut as UnionOut),

LKP_STG_SWP_CONSIDERATIONOut as (
	/* transType: "Lookup Procedure" */
Select 
	TRADE_ID as TRADE_ID,
	 UPFRONT_PAYMENT_CURRENCY as UPFRONT_PAYMENT_CURRENCY,
	 UPFRONT_PAYMENT_AMOUNT as UPFRONT_PAYMENT_AMOUNT,
	 UnionOut.in_TRADE_ID as in_TRADE_ID_1,
	 Union.TRADE_ID_TRA1 AS in_TRADE_ID_2 
FROM
	UnionOut as UnionOut 
 LEFT JOIN  ( select * from (
select 
*,TRADE_ID,row_number() over(partition by TRADE_ID order by rnk_fst desc nulls last) as rnk_lst
from
(
select *,TRADE_ID,row_number() over(partition by TRADE_ID order by TRADE_ID nulls last) as rnk_fst
from ( SELECT
       TRADE_ID as TRADE_ID,
       CURRENCY_CODE as UPFRONT_PAYMENT_CURRENCY,
       ABS(SUM(NVL(DECODE(PAY_RECEIVE_TYPE,'P',AMOUNT,0),0) - NVL(DECODE(PAY_RECEIVE_TYPE,'R',AMOUNT *(-1),0),0))) as UPFRONT_PAYMENT_AMOUNT
 FROM
       STG_SWP_CONSIDERATION as CONS
 WHERE   
   BUSINESS_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND 
      BATCH_ID =
 (SELECT
       BATCH_ID
 FROM
       BATCH_MASTER
 WHERE   
   BATCH_FEED_INFO= 'SWP_CORE_DATA_LOAD' AND  
   BATCH_BUSINESS_FROM_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND  
   BATCH_TYPE= 'EOD' AND  
   BATCH_STATUS= 'C') AND  
   ACTIVE_FLAG= 1
 GROUP BY
       TRADE_ID,
       CURRENCY_CODE )
) lkp_inner
) lkp_outer
where rnk_lst=1 ) 
ON
	TRADE_ID = in_TRADE_ID
 
),

EXP_SPL_EXTRACT_DATAOut as (
	/* transType: "Expression" */
Select 
	SRC_UTI_TRA as SRC_UTI_TRA,
	 UTI_TRA as UTI_TRA,
	 '{{ var("ADHOC_RUN") }}' as V_ADHOC_RUN,
	 V_ADHOC_RUN as O_ADHOC_RUN,
	 ( CASE WHEN V_ADHOC_RUN = 'Y' THEN TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ) ELSE null END ) as LKP_INPUT_BUSINESS_DATE,
	 ( CASE WHEN V_ADHOC_RUN = 'Y' THEN '{{ var("SERVICE") }}' ELSE null END ) as LKP_INPUT_SERVICE,
	 ( CASE WHEN V_ADHOC_RUN = 'Y' THEN dsf_1.SPL_MODE_RUN_ID ELSE null END ) as LKP_INPUT_SPL_MODE_RUN_ID,
	 ( CASE WHEN V_ADHOC_RUN = 'Y' THEN DECODE ( TRUE,
	 UTI_TRA IS NULL,
	 'NULL',
	 UTI_TRA ) ELSE null END ) as LKP_INPUT_UNIQUE_TRADE_ID,
	 'SWP' as SERVICE
From DSR_EXP_SPL_EXTRACT_DATAOut as DSR_EXP_SPL_EXTRACT_DATAOut
LEFT JOIN (
SELECT SPL_MODE_RUN_ID, SERVICE FROM (  SELECT SPL_MODE_RUN_ID, SERVICE,  ROW_NUMBER() OVER (PARTITION BY SERVICE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT SPL_MODE_RUN_ID, SERVICE,  ROW_NUMBER() OVER (PARTITION BY SERVICE ORDER BY SERVICE NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    RR_EMIR_TR_EXTRACTION_MODE )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.SERVICE = '{{ var("SERVICE") }}'
),

EXP_SPL_EXTRACT_DATAOut1 as (
	/* transType: "Expression" */
Select 
	SRC_UTI_TRA as SRC_UTI_TRA,
	 UTI_TRA as UTI_TRA,
	 '{{ var("ADHOC_RUN") }}' as V_ADHOC_RUN,
	 V_ADHOC_RUN as O_ADHOC_RUN,
	 ( CASE WHEN V_ADHOC_RUN = 'Y' THEN TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ) ELSE null END ) as LKP_INPUT_BUSINESS_DATE,
	 ( CASE WHEN V_ADHOC_RUN = 'Y' THEN '{{ var("SERVICE") }}' ELSE null END ) as LKP_INPUT_SERVICE,
	 ( CASE WHEN V_ADHOC_RUN = 'Y' THEN dsf_1.SPL_MODE_RUN_ID ELSE null END ) as LKP_INPUT_SPL_MODE_RUN_ID,
	 ( CASE WHEN V_ADHOC_RUN = 'Y' THEN DECODE ( TRUE,
	 UTI_TRA IS NULL,
	 'NULL',
	 UTI_TRA ) ELSE null END ) as LKP_INPUT_UNIQUE_TRADE_ID,
	 'SWP' as SERVICE
From DSR_EXP_SPL_EXTRACT_DATAOut as DSR_EXP_SPL_EXTRACT_DATAOut
LEFT JOIN (
SELECT SPL_MODE_RUN_ID, SERVICE FROM (  SELECT SPL_MODE_RUN_ID, SERVICE,  ROW_NUMBER() OVER (PARTITION BY SERVICE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT SPL_MODE_RUN_ID, SERVICE,  ROW_NUMBER() OVER (PARTITION BY SERVICE ORDER BY SERVICE NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    RR_EMIR_TR_EXTRACTION_MODE )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.SERVICE = '{{ var("SERVICE") }}'
),

LKP_COUNTERPARTIES_DIMOut as (
	/* transType: "Lookup Procedure" */
Select 
	ID as ID,
	 CLEARING_MEMBER_MNEMONIC as CLEARING_MEMBER_MNEMONIC,
	 LEGAL_ENTITY_IDENTIFIER as LEGAL_ENTITY_IDENTIFIER,
	 INCORPORATION_COUNTRY_CODE as INCORPORATION_COUNTRY_CODE,
	 UnionOut.IN_CLEARING_MEMBER_MNEMONIC as IN_CLEARING_MEMBER_MNEMONIC_1,
	 Union.CLEARING_MEMBER_LCH_CODE_PAR1 AS IN_CLEARING_MEMBER_MNEMONIC_2 
FROM
	UnionOut1 as UnionOut1 
 LEFT JOIN  ( select * from (
select 
*,CLEARING_MEMBER_MNEMONIC,row_number() over(partition by CLEARING_MEMBER_MNEMONIC order by rnk_fst desc nulls last) as rnk_lst
from
(
select *,CLEARING_MEMBER_MNEMONIC,row_number() over(partition by CLEARING_MEMBER_MNEMONIC order by CLEARING_MEMBER_MNEMONIC nulls last) as rnk_fst
from ( SELECT
       COUNTERPARTIES_DIM.ID as ID,
       NVL(COUNTERPARTIES_DIM.LEGAL_ENTITY_IDENTIFIER,COUNTERPARTIES_DIM.CFTC_INTERIM_COMPLIANT_ID) as LEGAL_ENTITY_IDENTIFIER,
       COUNTERPARTIES_DIM.CLEARING_MEMBER_MNEMONIC as CLEARING_MEMBER_MNEMONIC,
       COUNTERPARTIES_DIM.INCORPORATION_COUNTRY_CODE as INCORPORATION_COUNTRY_CODE
 FROM
       COUNTERPARTIES_DIM
 WHERE   
   EXCHANGE_MNEMONIC= '-2' AND  
   TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') BETWEEN EFFECTIVE_FROM_DATE AND  
   NVL(EFFECTIVE_TO_DATE,TO_DATE('31-DEC-2999','DD-MON-YYYY')) )
) lkp_inner
) lkp_outer
where rnk_lst=1 ) 
ON
	CLEARING_MEMBER_MNEMONIC = IN_CLEARING_MEMBER_MNEMONIC
 
),

