	 Union.o_ENTITY_ID1 AS i_ENTITY_ID,
	 Union.CLEARING_MEMBER_LCH_CODE_PAR1 AS i_MNEMONIC,
	 Union.SEGREGATED_ACCOUNT_PAR1 AS i_SERVICE_ACCOUNT_IDENTIFIER,
	 Union.o_BUSINESS_DATE1 AS i_BUSINESS_DATE,
	 Union.o_CALYPSO_BATCH_ID1 AS i_BATCH_ID 
FROM
	UnionOut4 as UnionOut4 
 LEFT JOIN  ( select * from (
select 
*,IH_EXCHANGE,ENTITY_ID,MNEMONIC,SERVICE_ACCOUNT_IDENTIFIER,row_number() over(partition by IH_EXCHANGE,ENTITY_ID,MNEMONIC,SERVICE_ACCOUNT_IDENTIFIER order by rnk_fst desc nulls last) as rnk_lst
from
(
select *,IH_EXCHANGE,ENTITY_ID,MNEMONIC,SERVICE_ACCOUNT_IDENTIFIER,row_number() over(partition by IH_EXCHANGE,ENTITY_ID,MNEMONIC,SERVICE_ACCOUNT_IDENTIFIER order by IH_EXCHANGE,ENTITY_ID,MNEMONIC,SERVICE_ACCOUNT_IDENTIFIER nulls last) as rnk_fst
from ( SELECT
       RR_BNK_EMIR_RPT_MEASURE_FACT.SUB_ACCOUNT as SUB_ACCOUNT,
       RR_BNK_EMIR_RPT_MEASURE_FACT.BATCH_ID as BATCH_ID,
       RR_BNK_EMIR_RPT_MEASURE_FACT.BUSINESS_DATE as BUSINESS_DATE,
       RR_BNK_EMIR_RPT_MEASURE_FACT.RR_BNK_SUB_ACCOUNT_ID as RR_BNK_SUB_ACCOUNT_ID,
       RR_BNK_EMIR_RPT_MEASURE_FACT.IM_POSTED as IM_POSTED,
       RR_BNK_EMIR_RPT_MEASURE_FACT.VM_POSTED as VM_POSTED,
       RR_BNK_EMIR_RPT_MEASURE_FACT.DEFAULT_CURRENCY as DEFAULT_CURRENCY,
       RR_BNK_EMIR_RPT_MEASURE_FACT.IM_RECEIVED as IM_RECEIVED,
       RR_BNK_EMIR_RPT_MEASURE_FACT.VM_RECEIVED as VM_RECEIVED,
       RR_BNK_EMIR_RPT_MEASURE_FACT.EXCESS_POSTED as EXCESS_POSTED,
       RR_BNK_EMIR_RPT_MEASURE_FACT.EXCESS_RECEIVED as EXCESS_RECEIVED,
       RR_BNK_EMIR_RPT_MEASURE_FACT.IH_EXCHANGE as IH_EXCHANGE,
       RR_BNK_EMIR_RPT_MEASURE_FACT.ENTITY_ID as ENTITY_ID,
       RR_BNK_EMIR_RPT_MEASURE_FACT.MNEMONIC as MNEMONIC,
       RR_BNK_EMIR_RPT_MEASURE_FACT.SERVICE_ACCOUNT_IDENTIFIER as SERVICE_ACCOUNT_IDENTIFIER
 FROM
       RR_BNK_EMIR_RPT_MEASURE_FACT
 WHERE   
   RR_BNK_EMIR_RPT_MEASURE_FACT.BUSINESS_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND 
      RR_BNK_EMIR_RPT_MEASURE_FACT.BATCH_ID =
 (SELECT
       BATCH_ID
 FROM
       BATCH_MASTER
 WHERE   
   BATCH_BUSINESS_FROM_DATE= TO_DATE('{{ var("BATCH_BUSINESS_DATE") }}','YYYYMMDD') AND  
   BATCH_FEED_INFO= 'BNK' AND  
   BATCH_STATUS= 'C') )
) lkp_inner
) lkp_outer
where rnk_lst=1 ) 
ON
	IH_EXCHANGE = i_IH_EXCHANGE
	AND ENTITY_ID = i_ENTITY_ID
	AND MNEMONIC = i_MNEMONIC
	AND SERVICE_ACCOUNT_IDENTIFIER = i_SERVICE_ACCOUNT_IDENTIFIER
 
),

