Select 
	SPL_MODE_RUN_ID as SPL_MODE_RUN_ID,
	 BUSINESS_DATE as BUSINESS_DATE,
	 SERVICE as SERVICE,
	 EXCHANGE_ID as EXCHANGE_ID,
	 UNIQUE_TRADE_ID as UNIQUE_TRADE_ID,
