	 EXECUTION_TIMESTAMP as EXECUTION_TIMESTAMP,
	 EXECUTION_TIMESTAMP_UTC as EXECUTION_TIMESTAMP_UTC,
	 MASTER_AGREEMENT as MASTER_AGREEMENT,
	 MASTER_AGREEMENT_VERSION as MASTER_AGREEMENT_VERSION,
	 DELTA_ACTION_TYPE as DELTA_ACTION_TYPE,
	 EXP_SPL_EXTRACT_DATA.LKP_INPUT_BUSINESS_DATE AS LKP_INPUT_BUSINESS_DATE,
	 EXP_SPL_EXTRACT_DATA.LKP_INPUT_SERVICE AS LKP_INPUT_SERVICE,
