	 EXP_SPL_EXTRACT_DATA.SRC_UTI_TRA AS LKP_INPUT_UNIQUE_TRADE_ID 
FROM
	EXP_SPL_EXTRACT_DATAOut as EXP_SPL_EXTRACT_DATAOut 
 LEFT JOIN  ( select * from (
select 
*,BUSINESS_DATE,SERVICE,SPL_MODE_RUN_ID,UNIQUE_TRADE_ID,row_number() over(partition by BUSINESS_DATE,SERVICE,SPL_MODE_RUN_ID,UNIQUE_TRADE_ID order by rnk_fst desc nulls last) as rnk_lst
from
(
select *,BUSINESS_DATE,SERVICE,SPL_MODE_RUN_ID,UNIQUE_TRADE_ID,row_number() over(partition by BUSINESS_DATE,SERVICE,SPL_MODE_RUN_ID,UNIQUE_TRADE_ID order by BUSINESS_DATE,SERVICE,SPL_MODE_RUN_ID,UNIQUE_TRADE_ID nulls last) as rnk_fst
from ( SELECT
       NVL(RR_EMIR_TR_SPL_EXTRACTION_DATA.UNIQUE_TRADE_ID,'NULL') as UNIQUE_TRADE_ID,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.POSITION_UTI as POSITION_UTI,
       NVL(RR_EMIR_TR_SPL_EXTRACTION_DATA.PRIOR_UTI,'NULL') as PRIOR_UTI,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.MEMBER_MNEMONIC as MEMBER_MNEMONIC,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.MEMBER_COUNTERPARTY_ID as MEMBER_COUNTERPARTY_ID,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.CONFIRMATION_TIMESTAMP as CONFIRMATION_TIMESTAMP,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.CONFIRMATION_TIMESTAMP_UTC as CONFIRMATION_TIMESTAMP_UTC,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.EXECUTION_TIMESTAMP as EXECUTION_TIMESTAMP,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.EXECUTION_TIMESTAMP_UTC as EXECUTION_TIMESTAMP_UTC,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.MASTER_AGREEMENT as MASTER_AGREEMENT,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.MASTER_AGREEMENT_VERSION as MASTER_AGREEMENT_VERSION,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.SPL_MODE_RUN_ID as SPL_MODE_RUN_ID,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.BUSINESS_DATE as BUSINESS_DATE,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.SERVICE as SERVICE,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.EXCHANGE_ID as EXCHANGE_ID,
       RR_EMIR_TR_SPL_EXTRACTION_DATA.DELTA_ACTION_TYPE as DELTA_ACTION_TYPE
 FROM
       RR_EMIR_TR_SPL_EXTRACTION_DATA
 JOIN
    RR_EMIR_TR_EXTRACTION_MODE
 WHERE   
   RR_EMIR_TR_EXTRACTION_MODE.SERVICE= '{{ var("SERVICE") }}' AND 
   RR_EMIR_TR_EXTRACTION_MODE.EMIR_TR_EXTRACTION_MODE NOT IN('NORMAL') AND  
   RR_EMIR_TR_EXTRACTION_MODE.SERVICE= RR_EMIR_TR_SPL_EXTRACTION_DATA.SERVICE AND  
   RR_EMIR_TR_EXTRACTION_MODE.SPL_MODE_RUN_ID= RR_EMIR_TR_SPL_EXTRACTION_DATA.SPL_MODE_RUN_ID )
) lkp_inner
) lkp_outer
where rnk_lst=1 ) 
ON
	BUSINESS_DATE = LKP_INPUT_BUSINESS_DATE
	AND SERVICE = LKP_INPUT_SERVICE
	AND SPL_MODE_RUN_ID = LKP_INPUT_SPL_MODE_RUN_ID
	AND UNIQUE_TRADE_ID = LKP_INPUT_UNIQUE_TRADE_ID
 
),

