	 ( CASE WHEN UPPER ( CONTRACTUAL_DEFINITIONS_TRA ) = 'ISDA2021' THEN INDEX_NAME_ISDA2021_RTEN ELSE INDEX_FULL_NAME_RTEN END ) as v_INDEX_FULL_NAME_RTEN,
