	 ( CASE WHEN UPPER ( PRODUCT_TYPE_TRA ) = UPPER ( 'InterestRate:IRSwap:Basis' ) AND ( PERIOD_NAME_DISPLAY_PAY1 = '1D' OR PERIOD_NAME_DISPLAY_REC1 = '1D' ) THEN 'BASIS_OIS' ELSE ( CASE WHEN UPPER ( PRODUCT_TYPE_TRA ) = UPPER ( 'InterestRate:IRSwap:Basis' ) AND PERIOD_NAME_DISPLAY_PAY1  !=  '1D' AND PERIOD_NAME_DISPLAY_REC1  !=  '1D' THEN 'BASIS' ELSE ( CASE WHEN UPPER ( PRODUCT_TYPE_TRA ) = UPPER ( 'InterestRate:FRA' ) THEN 'FRA_INDEX' ELSE ( CASE WHEN UPPER ( PRODUCT_TYPE_TRA ) = UPPER ( 'InterestRate:IRSwap:FixedFloat' ) AND IN ( UPPER ( LCH_PRODUCT_TYPE_TRA ),
	 'IRS',
	 'IRSND',
	 'VNS' ) = 1 THEN 'FIXED_FLOAT' ELSE ( CASE WHEN UPPER ( PRODUCT_TYPE_TRA ) = UPPER ( 'InterestRate:IRSwap:FixedFloat' ) AND IN ( UPPER ( LCH_PRODUCT_TYPE_TRA ),
	 'ZERO COUPON',
