SELECT STRING_VALUE3, STRING_VALUE2, STRING_VALUE4 FROM (  SELECT STRING_VALUE3, STRING_VALUE2, STRING_VALUE4,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE2, STRING_VALUE4 ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE3, STRING_VALUE2, STRING_VALUE4,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE2, STRING_VALUE4 ORDER BY STRING_VALUE2, STRING_VALUE4 NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    APPLICATION_VARIABLES )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
