LEFT JOIN (
SELECT MARKET_IDENTIFIER_CODE, EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT FROM (  SELECT MARKET_IDENTIFIER_CODE, EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT,  ROW_NUMBER() OVER (PARTITION BY EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT MARKET_IDENTIFIER_CODE, EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT,  ROW_NUMBER() OVER (PARTITION BY EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT ORDER BY EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT NULLS LAST) AS rnk_fst   FROM ( SELECT    APPLICATION_VARIABLES.VARIABLE_NAME as VARIABLE_NAME,    APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE,    UPPER(APPLICATION_VARIABLES.STRING_VALUE2) as EXECUTION_VENUE_NAME,    APPLICATION_VARIABLES.STRING_VALUE3 || '|' || APPLICATION_VARIABLES.STRING_VALUE8 as MARKET_IDENTIFIER_CODE,    NVL(UPPER(APPLICATION_VARIABLES.STRING_VALUE4),'-2') as EXECUTION_SOURCE_NAME,    NVL(UPPER(APPLICATION_VARIABLES.STRING_VALUE5),'-2') as EXECUTION_VENUE_TYPE,    NVL(UPPER(APPLICATION_VARIABLES.STRING_VALUE7),'-2') as ORIGINATING_EVENT FROM    APPLICATION_VARIABLES WHERE    APPLICATION_VARIABLES.STRING_VALUE= 'SWP' AND   APPLICATION_VARIABLES.VARIABLE_NAME= 'EMIR_VENUE_OF_EXECUTION' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.EXECUTION_VENUE_NAME = upper(DECODE(EXECUTION_VENUE_NAME_TRA AND dsf_3.EXECUTION_SOURCE_NAME = null AND dsf_3.EXECUTION_VENUE_TYPE = '-2' AND dsf_3.ORIGINATING_EVENT = EXECUTION_VENUE_NAME_TRA))
LEFT JOIN (
SELECT MARKET_IDENTIFIER_CODE, EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT FROM (  SELECT MARKET_IDENTIFIER_CODE, EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT,  ROW_NUMBER() OVER (PARTITION BY EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT MARKET_IDENTIFIER_CODE, EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT,  ROW_NUMBER() OVER (PARTITION BY EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT ORDER BY EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT NULLS LAST) AS rnk_fst   FROM ( SELECT    APPLICATION_VARIABLES.VARIABLE_NAME as VARIABLE_NAME,    APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE,    UPPER(APPLICATION_VARIABLES.STRING_VALUE2) as EXECUTION_VENUE_NAME,    APPLICATION_VARIABLES.STRING_VALUE3 || '|' || APPLICATION_VARIABLES.STRING_VALUE8 as MARKET_IDENTIFIER_CODE,    NVL(UPPER(APPLICATION_VARIABLES.STRING_VALUE4),'-2') as EXECUTION_SOURCE_NAME,    NVL(UPPER(APPLICATION_VARIABLES.STRING_VALUE5),'-2') as EXECUTION_VENUE_TYPE,    NVL(UPPER(APPLICATION_VARIABLES.STRING_VALUE7),'-2') as ORIGINATING_EVENT FROM    APPLICATION_VARIABLES WHERE    APPLICATION_VARIABLES.STRING_VALUE= 'SWP' AND   APPLICATION_VARIABLES.VARIABLE_NAME= 'EMIR_VENUE_OF_EXECUTION' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_4
ON dsf_4.EXECUTION_VENUE_NAME = '-2' AND dsf_4.EXECUTION_SOURCE_NAME = '-2' AND dsf_4.EXECUTION_VENUE_TYPE = '-2' AND dsf_4.ORIGINATING_EVENT = '-2'
LEFT JOIN (
SELECT ID, STRING_VALUE, STRING_VALUE2 FROM (  SELECT ID, STRING_VALUE, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE, STRING_VALUE2 ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT ID, STRING_VALUE, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE, STRING_VALUE2 ORDER BY STRING_VALUE, STRING_VALUE2 NULLS LAST) AS rnk_fst   FROM ( SELECT    APPLICATION_VARIABLES.ID as ID,    UPPER(APPLICATION_VARIABLES.STRING_VALUE) as STRING_VALUE,    UPPER(APPLICATION_VARIABLES.STRING_VALUE2) as STRING_VALUE2 FROM    APPLICATION_VARIABLES WHERE   VARIABLE_NAME= 'EMIR_SWP_COMPRESSION' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_5
ON dsf_5.STRING_VALUE = UPPER(TRANSACTION_STATUS_TRA) AND dsf_5.STRING_VALUE2 = V_COMPRESSION_EXERCISE
LEFT JOIN (
SELECT BST_APPLICABLE, YEAR, FROM_DT, TO_DT FROM (  SELECT BST_APPLICABLE, YEAR, FROM_DT, TO_DT,  ROW_NUMBER() OVER (PARTITION BY YEAR, FROM_DT, TO_DT ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT BST_APPLICABLE, YEAR, FROM_DT, TO_DT,  ROW_NUMBER() OVER (PARTITION BY YEAR, FROM_DT, TO_DT ORDER BY YEAR, FROM_DT, TO_DT NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    BST_DATE_RANGE )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_6
ON dsf_6.YEAR = V_EXECUTION_TIMESTAMP_ADJ_YEAR AND dsf_6.FROM_DT <= V_EXECUTION_TIMESTAMP_ADJ AND dsf_6.TO_DT >= V_EXECUTION_TIMESTAMP_ADJ
LEFT JOIN (
SELECT STRING_VALUE2, STRING_VALUE FROM (  SELECT STRING_VALUE2, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE2, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst   FROM ( SELECT    UPPER(APPLICATION_VARIABLES.STRING_VALUE) as STRING_VALUE,    APPLICATION_VARIABLES.STRING_VALUE2 as STRING_VALUE2 FROM    APPLICATION_VARIABLES WHERE   VARIABLE_NAME= 'EMIR_SWP_DAY_COUNT' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_7
ON dsf_7.STRING_VALUE = UPPER(DAY_COUNT_FRACTION_REC)
LEFT JOIN (
SELECT STRING_VALUE2, STRING_VALUE FROM (  SELECT STRING_VALUE2, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE2, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst   FROM ( SELECT    UPPER(APPLICATION_VARIABLES.STRING_VALUE) as STRING_VALUE,    APPLICATION_VARIABLES.STRING_VALUE2 as STRING_VALUE2 FROM    APPLICATION_VARIABLES WHERE   VARIABLE_NAME= 'EMIR_SWP_DAY_COUNT' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_8
ON dsf_8.STRING_VALUE = UPPER(DAY_COUNT_FRACTION_PAY)
LEFT JOIN (
SELECT STRING_VALUE2, STRING_VALUE FROM (  SELECT STRING_VALUE2, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE2, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst   FROM ( SELECT    UPPER(APPLICATION_VARIABLES.STRING_VALUE) as STRING_VALUE,    APPLICATION_VARIABLES.STRING_VALUE2 || '~' || APPLICATION_VARIABLES.STRING_VALUE3 as STRING_VALUE2 FROM    APPLICATION_VARIABLES WHERE   VARIABLE_NAME= 'EMIR_SWP_INDEX_NAME' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_9
ON dsf_9.STRING_VALUE = UPPER(v_INDEX_FULL_NAME_PTEN)
LEFT JOIN (
SELECT STRING_VALUE2, STRING_VALUE FROM (  SELECT STRING_VALUE2, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE2, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst   FROM ( SELECT    UPPER(APPLICATION_VARIABLES.STRING_VALUE) as STRING_VALUE,    APPLICATION_VARIABLES.STRING_VALUE2 || '~' || APPLICATION_VARIABLES.STRING_VALUE3 as STRING_VALUE2 FROM    APPLICATION_VARIABLES WHERE   VARIABLE_NAME= 'EMIR_SWP_INDEX_NAME' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_10
ON dsf_10.STRING_VALUE = UPPER(v_INDEX_FULL_NAME_RTEN)
LEFT JOIN (
SELECT DATE_VALUE, VARIABLE_NAME, VARIABLE_DATA_TYPE FROM (  SELECT DATE_VALUE, VARIABLE_NAME, VARIABLE_DATA_TYPE,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, VARIABLE_DATA_TYPE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT DATE_VALUE, VARIABLE_NAME, VARIABLE_DATA_TYPE,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, VARIABLE_DATA_TYPE ORDER BY VARIABLE_NAME, VARIABLE_DATA_TYPE NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    APPLICATION_VARIABLES )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_11
ON dsf_11.VARIABLE_NAME = 'EMIR_SWC_LIBO_CUTOVER_DATE' AND dsf_11.VARIABLE_DATA_TYPE = 'DATE'
LEFT JOIN (
SELECT SPL_MODE_RUN_ID, SERVICE FROM (  SELECT SPL_MODE_RUN_ID, SERVICE,  ROW_NUMBER() OVER (PARTITION BY SERVICE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT SPL_MODE_RUN_ID, SERVICE,  ROW_NUMBER() OVER (PARTITION BY SERVICE ORDER BY SERVICE NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    RR_EMIR_TR_EXTRACTION_MODE )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_12
ON dsf_12.SERVICE = '{{ var("SERVICE") }}'
),

