	 O_CALCULATION_BASIS3 as O_CALCULATION_BASIS3,
	 O_SERIES3 as O_SERIES3,
	 O_VERSION3 as O_VERSION3,
	 O_INDEX_FACTOR3 as O_INDEX_FACTOR3,
	 O_TRANCHE3 as O_TRANCHE3,
	 O_ATTACHMENT_POINT3 as O_ATTACHMENT_POINT3,
	 O_DETACHMENT_POINT3 as O_DETACHMENT_POINT3,
	 O_ACTION_TYPE3 as O_ACTION_TYPE3,
	 O_MESSAGE_TYPE3 as O_MESSAGE_TYPE3,
	 O_INTERNAL_ID3 as O_INTERNAL_ID3,
	 O_REPORTING_JURISDICTIONS3 as O_REPORTING_JURISDICTIONS3,
	 dsf_1.MARKET_IDENTIFIER_CODE as V_DEF_VENUE_DTLS,
	 SUBSTRING ( V_DEF_VENUE_DTLS,
	 1,
	 REGEXP_INSTR ( V_DEF_VENUE_DTLS,
