	 1,
	 1 ) -1 ) as V_DEF_VENUE_ID,
	 SUBSTRING ( V_DEF_VENUE_DTLS,
	 REGEXP_INSTR ( V_DEF_VENUE_DTLS,
	 '\\|',
	 1,
	 1 ) + 1,
	 1 ) as V_DEF_VENUE_EEA_IND,
	 dsf_2.STRING_VALUE2 as V_APPL_VAR_ISIN,
	 V_APPL_VAR_ISIN as O_APPL_VAR_ISIN,
