	 ( CASE WHEN IN ( UPPER ( O_ACTION_TYPE3 ),
	 'N',
	 'M',
	 'C',
	 'Z',
	 'R' ) = 1 THEN ( CASE WHEN O_EFFECTIVE_DATE_FIN3 < O_EXECUTION_TIMESTAMP_FIN3 THEN V_DEF_VENUE_ID ELSE O_VENUE_ID3 END ) ELSE null END ) as V_VENUE_ID,
	 V_VENUE_ID as O_VENUE_ID_VR_2_10,
	 ( CASE WHEN ( V_APPL_VAR_ISIN = 'Y' AND IN ( UPPER ( O_ACTION_TYPE3 ),
	 'N',
	 'M',
	 'C',
	 'Z',
	 'R' ) = 1 ) THEN ( CASE WHEN ( CASE WHEN V_LKP_EXT_TRD IS NULL THEN 0 ELSE 1 END ) = 0 AND V_VENUE_ID  !=  'XXXX' THEN 'XXXX' ELSE ( CASE WHEN ( O_CLEARING_TIMESTAMP_FIN3 IS NULL OR O_CLEARING_TIMESTAMP_FIN3 = '' ) THEN NULL ELSE ( CASE WHEN TO_DATE ( SUBSTRING ( O_CLEARING_TIMESTAMP_FIN3,
	 0,
	 10 ),
	 'YYYY-MM-DD' ) < V_LKP_MIFIDII_EFFECTIVE_DATE AND O_VENUE_ID_EEA = 'Y' THEN 'XXXX' ELSE V_VENUE_ID END ) END ) END ) ELSE V_VENUE_ID END ) as V_VENUE_ID3,
	 V_VENUE_ID3 as O_VENUE_ID,
	 ( CASE WHEN O_EFFECTIVE_DATE_FIN3 < O_EXECUTION_TIMESTAMP_FIN3 THEN V_DEF_VENUE_EEA_IND ELSE O_VENUE_ID_EEA END ) as V_VENUE_EEA_IND,
	 V_VENUE_EEA_IND as O_VENUE_EEA_IND,
	 DECODE ( O_CONTRACT_TYPE3,
	 'FW',
	 'Forward',
	 'FR',
	 'Forward',
	 'SW',
	 'Swap' ) as V_IN_INSTRUMENT_TYPE_ISIN,
	 UPPER ( V_IN_INSTRUMENT_TYPE_ISIN ) as O_IN_INSTRUMENT_TYPE_ISIN,
	 UPPER ( O_INSTRUMENT_CLASSIFICATION3 ) as O_IN_INSTRUMENT_CLASSIFICATION,
	 UPPER ( O_NOTIONAL_CURRENCY_13 ) as O_IN_NOTIONAL_CUR_ISIN,
	 ( CASE WHEN O_MATURITY_DATE_FIN3 IS NULL OR O_MATURITY_DATE_FIN3 = '' THEN NULL ELSE TO_DATE ( O_MATURITY_DATE_FIN3,
	 'YYYY-MM-DD' ) END ) as V_IN_EXPIRY_DATE_ISIN,
	 V_IN_EXPIRY_DATE_ISIN as O_IN_EXPIRY_DATE_ISIN,
	 ( CASE WHEN O_DELIVERY_TYPE3 = 'C' THEN 'CASH' ELSE 'PHYS' END ) as V_IN_DELIVERY_TYPE_ISIN,
	 UPPER ( V_IN_DELIVERY_TYPE_ISIN ) as O_IN_DELIVERY_TYPE_ISIN,
	 O_PRICE_MULTIPLIER_CONTRACT_SIZE3 as O_IN_PRICE_MULT,
	 O_FLOATING_REF_PERIOD_MULTIPLIER_LEG_13 as O_IN_REFRATE_TV_ISIN,
	 O_FLOATING_REF_PERIOD_MULTIPLIER_LEG_23 as O_IN_REFRATE_TV_ISIN_L2,
	 UPPER ( O_FLOATING_RATE_LEG_13 ) as O_IN_REFRATE_ISIN,
	 UPPER ( O_FLOATING_RATE_LEG_23 ) as O_IN_REFRATE_ISIN_L2,
	 DECODE ( O_FLOATING_REF_PERIOD_LEG_13,
	 'Y',
	 'YEAR',
	 'M',
	 'MNTH',
	 'W',
	 'WEEK',
	 'D',
	 'DAYS' ) as V_IN_REFRATE_TU_ISIN,
	 UPPER ( V_IN_REFRATE_TU_ISIN ) as O_IN_REFRATE_TU_ISIN,
	 DECODE ( O_FLOATING_REF_PERIOD_LEG_23,
	 'Y',
	 'YEAR',
	 'M',
	 'MNTH',
	 'W',
	 'WEEK',
	 'D',
	 'DAYS' ) as V_IN_REFRATE_TU_ISIN_L2,
	 UPPER ( V_IN_REFRATE_TU_ISIN_L2 ) as O_IN_REFRATE_TU_ISIN_L2,
	 UPPER ( O_FLOATING_RATE_LEG_23 ) as O_IN_OTHER_LEGREFRATE_ISIN,
	 O_FLOATING_REF_PERIOD_MULTIPLIER_LEG_23 as O_IN_OTHER_LEGREFRATE_TV_ISIN,
	 DECODE ( O_FLOATING_REF_PERIOD_LEG_23,
	 'Y',
	 'YEAR',
	 'M',
	 'MNTH',
	 'W',
	 'WEEK',
	 'D',
	 'DAYS' ) as V_IN_OTHER_LEGREFRATE_TU_ISIN,
	 UPPER ( V_IN_OTHER_LEGREFRATE_TU_ISIN ) as O_IN_OTHER_LEGREFRATE_TU_ISIN,
	 DECODE ( TRUE,
	 O_CLEARING_TIMESTAMP_FIN3 IS NULL OR O_CLEARING_TIMESTAMP_FIN3 = '',
	 NULL,
	 TO_TIMESTAMP ( ( SUBSTRING ( O_CLEARING_TIMESTAMP_FIN3,
	 1,
	 10 ) || ' ' || SUBSTRING ( O_CLEARING_TIMESTAMP_FIN3,
	 12,
	 8 ) ),
	 'YYYY-MM-DD HH24:MI:SS' ) ) as V_CLEARING_TIMESTAMP_FIN,
	 V_CLEARING_TIMESTAMP_FIN as O_CLEARING_TIMESTAMP_FIN_ISIN,
	 ( CASE WHEN V_LKP_EXT_TRD IS NULL THEN 0 ELSE 1 END ) as O_EXT_TRADE_IND,
	 DECODE ( TRUE,
	 V_ROWCOUNT > 99999,
	 2,
	 V_ROWCOUNT + 1 ) as V_ROWCOUNT,
	 NULL as O_NULL,
	 TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ) as O_BATCH_BUSINESS_DATE,
	 '{{ var("BATCH_ID") }}' as O_BATCH_ID,
	 '{{ var("PMWorkflowName") }}' as O_WORKFLOW_NAME,
	 '{{ var("PMMappingName") }}' as O_MAPPING_NAME,
	 '{{ var("APPLICATION_ID") }}' as O_APPLICATION_ID,
	 '{{ var("APPLICATION_NAME") }}' as O_APPLICATION_NAME,
	 '{{ var("SERVICE") }}' as O_SERVICE,
