	 UPPER ( FLOATING_RATE_LEG1_INDEX_NAME_FULL ) as O_FLOATING_RATE_LEG1_INDEX_NAME_FULL,
	 FLOATING_RATE_LEG2_INDEX_NAME_FULL as FLOATING_RATE_LEG2_INDEX_NAME_FULL,
	 UPPER ( FLOATING_RATE_LEG2_INDEX_NAME_FULL ) as O_FLOATING_RATE_LEG2_INDEX_NAME_FULL,
