	 NOTIONAL_23 as NOTIONAL_23,
	 CLEARING_MEMBER_LCH_CODE_PAR3 as CLEARING_MEMBER_LCH_CODE_PAR3
From DSR_EXP_FORMAT_NORMALOut as DSR_EXP_FORMAT_NORMALOut
LEFT JOIN (
SELECT MARKET_IDENTIFIER_CODE, EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT FROM (  SELECT MARKET_IDENTIFIER_CODE, EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT,  ROW_NUMBER() OVER (PARTITION BY EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT MARKET_IDENTIFIER_CODE, EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT,  ROW_NUMBER() OVER (PARTITION BY EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT ORDER BY EXECUTION_VENUE_NAME, EXECUTION_SOURCE_NAME, EXECUTION_VENUE_TYPE, ORIGINATING_EVENT NULLS LAST) AS rnk_fst   FROM ( SELECT    APPLICATION_VARIABLES.VARIABLE_NAME as VARIABLE_NAME,    APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE,    UPPER(APPLICATION_VARIABLES.STRING_VALUE2) as EXECUTION_VENUE_NAME,    APPLICATION_VARIABLES.STRING_VALUE3 || '|' || APPLICATION_VARIABLES.STRING_VALUE8 as MARKET_IDENTIFIER_CODE,    NVL(UPPER(APPLICATION_VARIABLES.STRING_VALUE4),'-2') as EXECUTION_SOURCE_NAME,    NVL(UPPER(APPLICATION_VARIABLES.STRING_VALUE5),'-2') as EXECUTION_VENUE_TYPE,    NVL(UPPER(APPLICATION_VARIABLES.STRING_VALUE7),'-2') as ORIGINATING_EVENT FROM    APPLICATION_VARIABLES WHERE    APPLICATION_VARIABLES.STRING_VALUE= 'SWP' AND   APPLICATION_VARIABLES.VARIABLE_NAME= 'EMIR_VENUE_OF_EXECUTION' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.EXECUTION_VENUE_NAME = '-2' AND dsf_1.EXECUTION_SOURCE_NAME = '-2' AND dsf_1.EXECUTION_VENUE_TYPE = '-2' AND dsf_1.ORIGINATING_EVENT = '-2'
LEFT JOIN (
SELECT STRING_VALUE2, VARIABLE_NAME, STRING_VALUE FROM (  SELECT STRING_VALUE2, VARIABLE_NAME, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE2, VARIABLE_NAME, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE ORDER BY VARIABLE_NAME, STRING_VALUE NULLS LAST) AS rnk_fst   FROM ( SELECT    APPLICATION_VARIABLES.STRING_VALUE2 as STRING_VALUE2,    APPLICATION_VARIABLES.VARIABLE_NAME as VARIABLE_NAME,    APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE FROM    APPLICATION_VARIABLES WHERE    APPLICATION_VARIABLES.VARIABLE_NAME= 'EMIR_ISIN_SOLUTION_ENABLED' AND   APPLICATION_VARIABLES.STRING_VALUE= 'SWP' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.VARIABLE_NAME = 'EMIR_ISIN_SOLUTION_ENABLED' AND dsf_2.STRING_VALUE = 'SWP'
LEFT JOIN (
SELECT DATE_VALUE, VARIABLE_NAME FROM (  SELECT DATE_VALUE, VARIABLE_NAME,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT DATE_VALUE, VARIABLE_NAME,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME ORDER BY VARIABLE_NAME NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    APPLICATION_VARIABLES )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.VARIABLE_NAME = 'EMIR_MIFIDII_EFFECTIVE_DATE'
LEFT JOIN (
SELECT STRING_VALUE, STRING_VALUE FROM (  SELECT STRING_VALUE, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst   FROM ( SELECT    UPPER(APPLICATION_VARIABLES.STRING_VALUE) as STRING_VALUE FROM    APPLICATION_VARIABLES WHERE   APPLICATION_VARIABLES.VARIABLE_NAME= 'EMIR_SWP_EXTERNAL_TRADES' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_4
ON dsf_4.STRING_VALUE = UPPER(ORIGINATING_EVENT_TRA)
LEFT JOIN (
SELECT ID, BATCH_ID, TARGET_TABLE_NAME, FILE_NAME FROM (  SELECT ID, BATCH_ID, TARGET_TABLE_NAME, FILE_NAME,  ROW_NUMBER() OVER (PARTITION BY BATCH_ID, TARGET_TABLE_NAME, FILE_NAME ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT ID, BATCH_ID, TARGET_TABLE_NAME, FILE_NAME,  ROW_NUMBER() OVER (PARTITION BY BATCH_ID, TARGET_TABLE_NAME, FILE_NAME ORDER BY BATCH_ID, TARGET_TABLE_NAME, FILE_NAME NULLS LAST) AS rnk_fst   FROM ( SELECT    BATCH_DETAILS.ID as ID,    BATCH_DETAILS.BATCH_ID as BATCH_ID,    BATCH_DETAILS.TARGET_TABLE_NAME as TARGET_TABLE_NAME,    BATCH_DETAILS.FILE_NAME as FILE_NAME,    BATCH_DETAILS.STATUS as STATUS FROM (SELECT    id,    TARGET_TABLE_NAME,    BATCH_ID,    STATUS,    ACTIVE_FLAG,    BATCH_DETAILS_START_TIME,    FILE_NAME,    RANK() OVER(partition by batch_id,TARGET_TABLE_NAME,FILE_NAME order by BATCH_DETAILS_START_TIME DESC) as RANK FROM    BATCH_DETAILS) BATCH_DETAILS WHERE    RANK= 1 AND   STATUS= 'I' AND   ACTIVE_FLAG= 1 )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_5
ON dsf_5.BATCH_ID = '{{ var("BATCH_ID") }}' AND dsf_5.TARGET_TABLE_NAME = '{{ var("TARGET_NAME") }}' AND dsf_5.FILE_NAME = '{{ var("SOURCE_NAME") }}'
),

