from
(
select *,INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,OTHER_LEGREFRATE,OTHER_LEGREFRATE_TV,OTHER_LEGREFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE,row_number() over(partition by INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,OTHER_LEGREFRATE,OTHER_LEGREFRATE_TV,OTHER_LEGREFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE order by INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,OTHER_LEGREFRATE,OTHER_LEGREFRATE_TV,OTHER_LEGREFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE nulls last) as rnk_fst
from ( SELECT
    ISIN as ISIN,
    LAG(EFFECTIVE_FROM_DATE,1) OVER(PARTITION BY INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,OTHER_LEGREFRATE,OTHER_LEGREFRATE_TV,OTHER_LEGREFRATE_TU,EFFECTIVE_FROM_DATE ORDER BY EFFECTIVE_FROM_DATE) as PREV_EF_FRM_DT,
    LAG(EFFECTIVE_TO_DATE,1) OVER(PARTITION BY INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,OTHER_LEGREFRATE,OTHER_LEGREFRATE_TV,OTHER_LEGREFRATE_TU,EFFECTIVE_FROM_DATE ORDER BY EFFECTIVE_FROM_DATE) as PREV_EF_TO_DT,
    LEAD(EFFECTIVE_FROM_DATE,1) OVER(PARTITION BY INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,OTHER_LEGREFRATE,OTHER_LEGREFRATE_TV,OTHER_LEGREFRATE_TU,EFFECTIVE_FROM_DATE ORDER BY EFFECTIVE_FROM_DATE) as NEXT_EF_FRM_DT,
    LEAD(EFFECTIVE_TO_DATE,1) OVER(PARTITION BY INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,OTHER_LEGREFRATE,OTHER_LEGREFRATE_TV,OTHER_LEGREFRATE_TU,EFFECTIVE_FROM_DATE ORDER BY EFFECTIVE_FROM_DATE) as NEXT_EF_TO_DT,
    INSTRUMENT_TYPE as INSTRUMENT_TYPE,
    USE_CASE as USE_CASE,
    CLASSIF_TYPE as CLASSIF_TYPE,
    NOTIONAL_CUR as NOTIONAL_CUR,
    EXPIRY_DATE as EXPIRY_DATE,
    DELIVERY_TYPE as DELIVERY_TYPE,
    PRICE_MULT as PRICE_MULT,
    REFRATE_TV as REFRATE_TV,
    REFRATE as REFRATE,
    REFRATE_TU as REFRATE_TU,
    OTHER_LEGREFRATE as OTHER_LEGREFRATE,
    OTHER_LEGREFRATE_TV as OTHER_LEGREFRATE_TV,
    OTHER_LEGREFRATE_TU as OTHER_LEGREFRATE_TU,
    EFFECTIVE_FROM_DATE as EFFECTIVE_FROM_DATE,
    EFFECTIVE_TO_DATE as EFFECTIVE_TO_DATE
 FROM(
 SELECT
    SECURITY_IDENTIFIERS_DIM.ISIN as ISIN,
    UPPER(SECURITY_IDENTIFIERS_DIM.INSTRUMENT_TYPE) as INSTRUMENT_TYPE,
    UPPER(SECURITY_IDENTIFIERS_DIM.USE_CASE) as USE_CASE,
    UPPER(SECURITY_IDENTIFIERS_DIM.CLASSIF_TYPE) as CLASSIF_TYPE,
    UPPER(SECURITY_IDENTIFIERS_DIM.NOTIONAL_CUR) as NOTIONAL_CUR,
    SECURITY_IDENTIFIERS_DIM.EXPIRY_DATE as EXPIRY_DATE,
    UPPER(SECURITY_IDENTIFIERS_DIM.DELIVERY_TYPE) as DELIVERY_TYPE,
    SECURITY_IDENTIFIERS_DIM.PRICE_MULT as PRICE_MULT,
    SECURITY_IDENTIFIERS_DIM.REFRATE_TV as REFRATE_TV,
    UPPER(SECURITY_IDENTIFIERS_DIM.REFRATE) as REFRATE,
    UPPER(SECURITY_IDENTIFIERS_DIM.REFRATE_TU) as REFRATE_TU,
    UPPER(SECURITY_IDENTIFIERS_DIM.OTHER_LEGREFRATE) as OTHER_LEGREFRATE,
    SECURITY_IDENTIFIERS_DIM.OTHER_LEGREFRATE_TV as OTHER_LEGREFRATE_TV,
    UPPER(SECURITY_IDENTIFIERS_DIM.OTHER_LEGREFRATE_TU) as OTHER_LEGREFRATE_TU,
    SECURITY_IDENTIFIERS_DIM.EFFECTIVE_FROM_DATE as EFFECTIVE_FROM_DATE,
    NVL(SECURITY_IDENTIFIERS_DIM.EFFECTIVE_TO_DATE,TO_DATE('31-DEC-2099','DD-MON-YYYY')) as EFFECTIVE_TO_DATE
 FROM
    SECURITY_IDENTIFIERS_DIM
 WHERE  
  UPPER(ASSET_CLASS)= UPPER('RATES') AND 
  UPPER(ISIN_LEVEL)= UPPER('INSTREFDATAREPORTING') AND 
  UPPER(USE_CASE) LIKE UPPER('BASIS%') AND 
   ISIN NOT IN
 (SELECT
    ISIN
 FROM
    SECURITY_IDENTIFIERS_DIM
 WHERE  
  UPPER(ASSET_CLASS)= UPPER('RATES') AND 
  UPPER(STATUS) IN(UPPER('DELETED'),UPPER('DEPRECATED')))
 UNION 
 SELECT
    SECURITY_IDENTIFIERS_DIM.ISIN as ISIN,
    UPPER(SECURITY_IDENTIFIERS_DIM.INSTRUMENT_TYPE) as INSTRUMENT_TYPE,
    UPPER(SECURITY_IDENTIFIERS_DIM.USE_CASE) as USE_CASE,
    UPPER(SECURITY_IDENTIFIERS_DIM.CLASSIF_TYPE) as CLASSIF_TYPE,
    UPPER(SECURITY_IDENTIFIERS_DIM.NOTIONAL_CUR) as NOTIONAL_CUR,
    SECURITY_IDENTIFIERS_DIM.EXPIRY_DATE as EXPIRY_DATE,
    UPPER(SECURITY_IDENTIFIERS_DIM.DELIVERY_TYPE) as DELIVERY_TYPE,
    SECURITY_IDENTIFIERS_DIM.PRICE_MULT as PRICE_MULT,
    SECURITY_IDENTIFIERS_DIM.OTHER_LEGREFRATE_TV as REFRATE_TV,
    UPPER(SECURITY_IDENTIFIERS_DIM.OTHER_LEGREFRATE) as REFRATE,
    UPPER(SECURITY_IDENTIFIERS_DIM.OTHER_LEGREFRATE_TU) as REFRATE_TU,
    UPPER(SECURITY_IDENTIFIERS_DIM.REFRATE) as OTHER_LEGREFRATE,
    SECURITY_IDENTIFIERS_DIM.REFRATE_TV as OTHER_LEGREFRATE_TV,
    UPPER(SECURITY_IDENTIFIERS_DIM.REFRATE_TU) as OTHER_LEGREFRATE_TU,
    SECURITY_IDENTIFIERS_DIM.EFFECTIVE_FROM_DATE as EFFECTIVE_FROM_DATE,
    NVL(SECURITY_IDENTIFIERS_DIM.EFFECTIVE_TO_DATE,TO_DATE('31-DEC-2099','DD-MON-YYYY')) as EFFECTIVE_TO_DATE
 FROM
    SECURITY_IDENTIFIERS_DIM
 WHERE  
  UPPER(ASSET_CLASS)= UPPER('RATES') AND 
  UPPER(ISIN_LEVEL)= UPPER('INSTREFDATAREPORTING') AND 
  UPPER(USE_CASE) LIKE UPPER('BASIS%') AND 
   ISIN NOT IN
 (SELECT
    ISIN
 FROM
    SECURITY_IDENTIFIERS_DIM
 WHERE  
  UPPER(ASSET_CLASS)= UPPER('RATES') AND 
  UPPER(STATUS) IN(UPPER('DELETED'),UPPER('DEPRECATED'))) AND 
  (REFRATE != OTHER_LEGREFRATE OR REFRATE_TU != OTHER_LEGREFRATE_TU OR REFRATE_TV != OTHER_LEGREFRATE_TV))
 ORDER BY
    EFFECTIVE_FROM_DATE )
) lkp_inner
) lkp_outer
where rnk_lst=1 ) 
ON
	INSTRUMENT_TYPE = in_INSTRUMENT_TYPE
	AND USE_CASE = in_USE_CASE
	AND CLASSIF_TYPE = in_CLASSIF_TYPE
	AND NOTIONAL_CUR = in_NOTIONAL_CUR
	AND EXPIRY_DATE = in_EXPIRY_DATE
	AND DELIVERY_TYPE = in_DELIVERY_TYPE
	AND PRICE_MULT = in_PRICE_MULT
	AND REFRATE_TV = in_REFRATE_TV
	AND REFRATE = in_REFRATE
	AND REFRATE_TU = in_REFRATE_TU
	AND OTHER_LEGREFRATE = in_OTHER_LEGREFRATE
	AND OTHER_LEGREFRATE_TV = in_OTHER_LEGREFRATE_TV
	AND OTHER_LEGREFRATE_TU = in_OTHER_LEGREFRATE_TU
	AND EFFECTIVE_FROM_DATE <= in_DATE
	AND EFFECTIVE_TO_DATE >= in_DATE
	AND EXPIRY_DATE >= in_DATE
 
),

EXP_INFLATION_SWAPOut as (
	/* transType: "Expression" */
Select 
	O_CLEARING_TIMESTAMP_FIN_ISIN3 as O_CLEARING_TIMESTAMP_FIN_ISIN3,
	 dsf_1.STRING_VALUE3 as V_APP_VAR_SEARCH_1,
	 dsf_2.STRING_VALUE3 as V_APP_VAR_SEARCH_2,
	 dsf_3.STRING_VALUE3 as V_APP_VAR_SEARCH_3,
	 SUBSTRING ( V_APP_VAR_SEARCH_1,
	 1,
	 REGEXP_INSTR ( V_APP_VAR_SEARCH_1,
	 '\\|',
	 1,
	 1 ) -1 ) as O_REFRATE_TV_SEARCH_1,
	 SUBSTRING ( V_APP_VAR_SEARCH_1,
	 REGEXP_INSTR ( V_APP_VAR_SEARCH_1,
	 '\\|',
	 1,
	 1 ) + 1,
	 4 ) as O_REFRATE_TU_SEARCH_1,
	 SUBSTRING ( V_APP_VAR_SEARCH_2,
	 1,
	 REGEXP_INSTR ( V_APP_VAR_SEARCH_2,
	 '\\|',
	 1,
	 1 ) -1 ) as O_REFRATE_TV_SEARCH_2,
	 SUBSTRING ( V_APP_VAR_SEARCH_2,
	 REGEXP_INSTR ( V_APP_VAR_SEARCH_2,
	 '\\|',
	 1,
	 1 ) + 1,
	 4 ) as O_REFRATE_TU_SEARCH_2,
	 SUBSTRING ( V_APP_VAR_SEARCH_3,
	 1,
	 REGEXP_INSTR ( V_APP_VAR_SEARCH_3,
	 '\\|',
	 1,
	 1 ) -1 ) as O_REFRATE_TV_SEARCH_3,
	 SUBSTRING ( V_APP_VAR_SEARCH_3,
	 REGEXP_INSTR ( V_APP_VAR_SEARCH_3,
	 '\\|',
	 1,
	 1 ) + 1,
	 4 ) as O_REFRATE_TU_SEARCH_3
From DSR_RTR_PRODUCT_NAMEOut as DSR_RTR_PRODUCT_NAMEOut
WHERE PRODUCT_NAME = 'BASIS'
LEFT JOIN (
SELECT STRING_VALUE3, STRING_VALUE FROM (  SELECT STRING_VALUE3, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE3, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst   FROM ( SELECT    UPPER(STRING_VALUE2) || '|' || UPPER(STRING_VALUE3) as STRING_VALUE3,    APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE FROM    APPLICATION_VARIABLES WHERE   APPLICATION_VARIABLES.VARIABLE_NAME= 'EMIR_SWP_INFLATION_SWP_REFRATE' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.STRING_VALUE = 'SEARCH_1'
LEFT JOIN (
SELECT STRING_VALUE3, STRING_VALUE FROM (  SELECT STRING_VALUE3, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE3, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst   FROM ( SELECT    UPPER(STRING_VALUE2) || '|' || UPPER(STRING_VALUE3) as STRING_VALUE3,    APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE FROM    APPLICATION_VARIABLES WHERE   APPLICATION_VARIABLES.VARIABLE_NAME= 'EMIR_SWP_INFLATION_SWP_REFRATE' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.STRING_VALUE = 'SEARCH_2'
LEFT JOIN (
SELECT STRING_VALUE3, STRING_VALUE FROM (  SELECT STRING_VALUE3, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE3, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst   FROM ( SELECT    UPPER(STRING_VALUE2) || '|' || UPPER(STRING_VALUE3) as STRING_VALUE3,    APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE FROM    APPLICATION_VARIABLES WHERE   APPLICATION_VARIABLES.VARIABLE_NAME= 'EMIR_SWP_INFLATION_SWP_REFRATE' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.STRING_VALUE = 'SEARCH_3'
),

