LKP_SECURITY_IDENTIFIERS_DIM_FRA_FIXED_FLOAT_ZEROOut as (
	/* transType: "Lookup Procedure" */
Select 
	ISIN as ISIN,
	 PREV_EF_FRM_DT as PREV_EF_FRM_DT,
	 PREV_EF_TO_DT as PREV_EF_TO_DT,
	 NEXT_EF_FRM_DT as NEXT_EF_FRM_DT,
	 NEXT_EF_TO_DT as NEXT_EF_TO_DT,
	 RTR_PRODUCT_NAME.O_IN_INSTRUMENT_TYPE_ISIN5 AS in_INSTRUMENT_TYPE,
	 RTR_PRODUCT_NAME.PRODUCT_NAME5 AS in_USE_CASE,
	 RTR_PRODUCT_NAME.O_IN_INSTRUMENT_CLASSIFICATION5 AS in_CLASSIF_TYPE,
	 RTR_PRODUCT_NAME.O_IN_NOTIONAL_CUR_ISIN5 AS in_NOTIONAL_CUR,
	 RTR_PRODUCT_NAME.O_IN_EXPIRY_DATE_ISIN5 AS in_EXPIRY_DATE,
	 RTR_PRODUCT_NAME.O_IN_DELIVERY_TYPE_ISIN5 AS in_DELIVERY_TYPE,
	 RTR_PRODUCT_NAME.O_IN_PRICE_MULT5 AS in_PRICE_MULT,
	 RTR_PRODUCT_NAME.O_IN_REFRATE_TV_ISIN_L25 AS in_REFRATE_TV,
	 RTR_PRODUCT_NAME.O_FLOATING_RATE_LEG2_INDEX_NAME_FULL5 AS in_REFRATE,
	 RTR_PRODUCT_NAME.O_IN_REFRATE_TU_ISIN_L25 AS in_REFRATE_TU,
	 RTR_PRODUCT_NAME.O_CLEARING_TIMESTAMP_FIN_ISIN5 AS in_DATE 
FROM
	RTR_PRODUCT_NAMEOut as RTR_PRODUCT_NAMEOut 
 LEFT JOIN ( select * from (
select 
*,INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE,row_number() over(partition by INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE order by rnk_fst desc nulls last) as rnk_lst
from
(
select *,INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE,row_number() over(partition by INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE order by INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE nulls last) as rnk_fst
from ( SELECT
    ISIN as ISIN,
    LAG(EFFECTIVE_FROM_DATE,1) OVER(PARTITION BY INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE ORDER BY EFFECTIVE_FROM_DATE) as PREV_EF_FRM_DT,
