	 EXP_INFLATION_SWAP.O_CLEARING_TIMESTAMP_FIN_ISIN3 AS in_DATE 
FROM
	EXP_INFLATION_SWAPOut2 as EXP_INFLATION_SWAPOut2 
 LEFT JOIN ( select * from (
select 
*,INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE,row_number() over(partition by INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE order by rnk_fst desc nulls last) as rnk_lst
from
(
select *,INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE,row_number() over(partition by INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE order by INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE,EFFECTIVE_TO_DATE,EXPIRY_DATE nulls last) as rnk_fst
from ( SELECT
    ISIN as ISIN,
    LAG(EFFECTIVE_FROM_DATE,1) OVER(PARTITION BY INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE ORDER BY EFFECTIVE_FROM_DATE) as PREV_EF_FRM_DT,
    LAG(EFFECTIVE_TO_DATE,1) OVER(PARTITION BY INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE ORDER BY EFFECTIVE_FROM_DATE) as PREV_EF_TO_DT,
    LEAD(EFFECTIVE_FROM_DATE,1) OVER(PARTITION BY INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE ORDER BY EFFECTIVE_FROM_DATE) as NEXT_EF_FRM_DT,
    LEAD(EFFECTIVE_TO_DATE,1) OVER(PARTITION BY INSTRUMENT_TYPE,USE_CASE,CLASSIF_TYPE,NOTIONAL_CUR,EXPIRY_DATE,DELIVERY_TYPE,PRICE_MULT,REFRATE_TV,REFRATE,REFRATE_TU,EFFECTIVE_FROM_DATE ORDER BY EFFECTIVE_FROM_DATE) as NEXT_EF_TO_DT,
    INSTRUMENT_TYPE as INSTRUMENT_TYPE,
    USE_CASE as USE_CASE,
    CLASSIF_TYPE as CLASSIF_TYPE,
    NOTIONAL_CUR as NOTIONAL_CUR,
    EXPIRY_DATE as EXPIRY_DATE,
    DELIVERY_TYPE as DELIVERY_TYPE,
    PRICE_MULT as PRICE_MULT,
    REFRATE_TV as REFRATE_TV,
    REFRATE as REFRATE,
    REFRATE_TU as REFRATE_TU,
    EFFECTIVE_FROM_DATE as EFFECTIVE_FROM_DATE,
    EFFECTIVE_TO_DATE as EFFECTIVE_TO_DATE
 FROM(
 SELECT
    SECURITY_IDENTIFIERS_DIM.ISIN as ISIN,
    UPPER(SECURITY_IDENTIFIERS_DIM.INSTRUMENT_TYPE) as INSTRUMENT_TYPE,
    UPPER(SECURITY_IDENTIFIERS_DIM.USE_CASE) as USE_CASE,
    UPPER(SECURITY_IDENTIFIERS_DIM.CLASSIF_TYPE) as CLASSIF_TYPE,
    UPPER(SECURITY_IDENTIFIERS_DIM.NOTIONAL_CUR) as NOTIONAL_CUR,
    SECURITY_IDENTIFIERS_DIM.EXPIRY_DATE as EXPIRY_DATE,
    UPPER(SECURITY_IDENTIFIERS_DIM.DELIVERY_TYPE) as DELIVERY_TYPE,
    SECURITY_IDENTIFIERS_DIM.PRICE_MULT as PRICE_MULT,
    SECURITY_IDENTIFIERS_DIM.REFRATE_TV as REFRATE_TV,
    UPPER(SECURITY_IDENTIFIERS_DIM.REFRATE) as REFRATE,
    UPPER(SECURITY_IDENTIFIERS_DIM.REFRATE_TU) as REFRATE_TU,
    SECURITY_IDENTIFIERS_DIM.EFFECTIVE_FROM_DATE as EFFECTIVE_FROM_DATE,
    NVL(SECURITY_IDENTIFIERS_DIM.EFFECTIVE_TO_DATE,TO_DATE('31-DEC-2099','DD-MON-YYYY')) as EFFECTIVE_TO_DATE
 FROM
    SECURITY_IDENTIFIERS_DIM
 WHERE  
  UPPER(ASSET_CLASS)= UPPER('RATES') AND 
  UPPER(ISIN_LEVEL)= UPPER('INSTREFDATAREPORTING') AND 
   ISIN NOT IN
 (SELECT
    ISIN
 FROM
    SECURITY_IDENTIFIERS_DIM
 WHERE  
  UPPER(ASSET_CLASS)= UPPER('RATES') AND 
  UPPER(STATUS) IN(UPPER('DELETED'),UPPER('DEPRECATED'))))
 ORDER BY
    EFFECTIVE_FROM_DATE )
) lkp_inner
) lkp_outer
where rnk_lst=1 ) 
ON
	INSTRUMENT_TYPE = in_INSTRUMENT_TYPE
	AND USE_CASE = in_USE_CASE
	AND CLASSIF_TYPE = in_CLASSIF_TYPE
	AND NOTIONAL_CUR = in_NOTIONAL_CUR
	AND EXPIRY_DATE = in_EXPIRY_DATE
	AND DELIVERY_TYPE = in_DELIVERY_TYPE
	AND PRICE_MULT = in_PRICE_MULT
	AND REFRATE_TV = in_REFRATE_TV
	AND REFRATE = in_REFRATE
	AND REFRATE_TU = in_REFRATE_TU
	AND EFFECTIVE_FROM_DATE <= in_DATE
	AND EFFECTIVE_TO_DATE >= in_DATE
	AND EXPIRY_DATE >= in_DATE
 
),

