	 CLEARING_MEMBER_MNEMONIC3 as CLEARING_MEMBER_MNEMONIC3,
	 O_SORT_ORDER13 as O_SORT_ORDER13,
	 DELTA_ACTION_TYPE3 as DELTA_ACTION_TYPE3,
	 '{{ var("EMIR_TR_EXTRACTION_MODE") }}' as O_EMIR_TR_EXTRACTION_MODE,
	 FLOATING_RATE_LEG1_INDEX_NAME_FULL as FLOATING_RATE_LEG1_INDEX_NAME_FULL,
	 FLOATING_RATE_LEG2_INDEX_NAME_FULL as FLOATING_RATE_LEG2_INDEX_NAME_FULL,
	 FileName13 as FileName13,
	 BATCH_DETAILS_ID as BATCH_DETAILS_ID,
	 o_PRODUCT_NAME3 as o_PRODUCT_NAME3,
	 O_CLEARING_TIMESTAMP_FIN_ISIN as O_CLEARING_TIMESTAMP_FIN_ISIN,
	 ISIN as ISIN,
	 PREV_EF_FRM_DT as PREV_EF_FRM_DT,
	 PREV_EF_TO_DT as PREV_EF_TO_DT,
