	 dsf_3.TOTV_INDICATOR as V_LKP_TOTV_IND,
	 O_EXT_TRADE_IND as O_EXT_TRADE_IND,
	 ( CASE WHEN IN ( O_ACTION_TYPE3,
	 'N',
	 'M',
	 'C',
	 'R',
	 'Z' ) = 1 THEN ( CASE WHEN ( O_CLEARING_TIMESTAMP_FIN3 IS NULL OR O_CLEARING_TIMESTAMP_FIN3 = '' ) THEN NULL ELSE ( CASE WHEN O_APPL_VAR_ISIN = 'Y' AND TO_DATE ( SUBSTRING ( O_CLEARING_TIMESTAMP_FIN3,
	 0,
	 10 ),
	 'YYYY-MM-DD' ) >= V_LKP_MIFIDII_EFFECTIVE_DATE AND ISIN IS NOT NULL AND IN ( O_ACTION_TYPE3,
	 'N',
	 'M',
	 'C',
	 'R',
	 'Z' ) = 1 AND O_EXT_TRADE_IND = 1 THEN 'Y' ELSE 'N' END ) END ) ELSE 'N' END ) as V_ISIN_FLAG,
	 ( CASE WHEN V_ISIN_FLAG = 'Y' THEN DECODE ( TRUE,
	 ( O_VENUE_ID3  !=  'XXXX' AND O_VENUE_ID_EEA = 'Y' ),
	 O_VENUE_ID3,
	 ( O_VENUE_ID3 = 'XXXX' AND ( CASE WHEN V_LKP_TOTV_IND IS NULL THEN 0 ELSE V_LKP_TOTV_IND END ) = 1 ),
	 'XOFF',
	 O_VENUE_ID3 ) ELSE O_VENUE_ID3 END ) as V_VENUE_ID_FINAL,
	 ( CASE WHEN V_ISIN_FLAG = 'Y' THEN DECODE ( TRUE,
	 ( O_VENUE_ID3  !=  'XXXX' AND O_VENUE_ID_EEA = 'Y' ),
	 ISIN,
	 ( O_VENUE_ID3 = 'XXXX' AND ( CASE WHEN V_LKP_TOTV_IND IS NULL THEN 0 ELSE V_LKP_TOTV_IND END ) = 1 ),
	 ISIN,
	 NULL ) ELSE NULL END ) as V_INSTRUMENT_IDENTIFICATION_FINAL,
	 ( CASE WHEN V_ISIN_FLAG = 'Y' THEN DECODE ( TRUE,
	 ( O_VENUE_ID3  !=  'XXXX' AND O_VENUE_ID_EEA = 'Y' ),
	 'I',
	 ( O_VENUE_ID3 = 'XXXX' AND ( CASE WHEN V_LKP_TOTV_IND IS NULL THEN 0 ELSE V_LKP_TOTV_IND END ) = 1 ),
	 'I',
	 NULL ) ELSE NULL END ) as V_INSTRUMENT_IDENTIFICATION_TYPE_FINAL,
	 V_VENUE_ID_FINAL as O_VENUE_ID_FINAL,
	 O_APPL_VAR_ISIN as ISIN_SOLUTION_FLG,
	 O_ACTION_TYPE3 as ACTION_TYPE,
	 O_CLEARING_TIMESTAMP_FIN_mplt3 as CLEARING_TIMESTAMP,
	 V_VENUE_ID_FINAL as VENUE_OF_EXEC,
	 O_VENUE_ID_EEA as EEA_IND,
	 V_INSTRUMENT_IDENTIFICATION_FINAL as INSTRUMENT_IDENTIFICATION,
	 ( CASE WHEN ( ISIN_SOLUTION_FLG = 'Y' AND IN ( UPPER ( ACTION_TYPE ),
	 'N',
	 'M',
	 'C',
	 'Z',
	 'R' ) = 1 AND CLEARING_TIMESTAMP >= TO_VARCHAR ( V_LKP_MIFIDII_EFFECTIVE_DATE,
	 'YYYY-MM-DD HH24:MI:SS' ) AND VENUE_OF_EXEC  !=  'XXXX' AND EEA_IND = 'Y' AND INSTRUMENT_IDENTIFICATION IS NULL ) THEN 'XXXX' ELSE V_VENUE_ID_FINAL END ) as O_VENUE_ID_OVERRIDE_TGT,
	 ( CASE WHEN ( ISIN_SOLUTION_FLG = 'Y' AND IN ( UPPER ( ACTION_TYPE ),
	 'N',
	 'M',
	 'C',
	 'Z',
	 'R' ) = 1 AND CLEARING_TIMESTAMP >= TO_VARCHAR ( V_LKP_MIFIDII_EFFECTIVE_DATE,
	 'YYYY-MM-DD HH24:MI:SS' ) ) THEN ( CASE WHEN VENUE_OF_EXEC  !=  'XXXX' AND EEA_IND = 'Y' AND INSTRUMENT_IDENTIFICATION IS NULL THEN 'XXXX' ELSE null END ) ELSE NULL END ) as O_VENUE_ID_OVERRIDE_FLT,
	 V_INSTRUMENT_IDENTIFICATION_FINAL as O_INSTRUMENT_IDENTIFICATION_FINAL,
	 V_INSTRUMENT_IDENTIFICATION_TYPE_FINAL as O_INSTRUMENT_IDENTIFICATION_TYPE_FINAL,
	 ( CASE WHEN V_ISIN_FLAG = 'Y' AND ( ( CASE WHEN PREV_EF_FRM_DT IS NULL THEN FALSE ELSE ( O_CLEARING_TIMESTAMP_FIN_ISIN >= PREV_EF_FRM_DT AND O_CLEARING_TIMESTAMP_FIN_ISIN <= PREV_EF_TO_DT ) END ) OR ( ( CASE WHEN NEXT_EF_FRM_DT IS NULL THEN FALSE ELSE ( O_CLEARING_TIMESTAMP_FIN_ISIN >= NEXT_EF_FRM_DT AND O_CLEARING_TIMESTAMP_FIN_ISIN <= NEXT_EF_TO_DT ) END ) ) ) THEN 'Y' ELSE 'N' END ) as ISIN_TOTV_MULTIPLE_MATCH_FLG,
	 SEGREGATED_ACCOUNT_PAR3 as SEGREGATED_ACCOUNT_PAR3,
	 O_VENUE_ID_LKP1_2_11 as O_VENUE_ID_LKP1_2_11,
	 O_VENUE_ID_VR_2_10 as O_VENUE_ID_VR_2_10,
	 CFI_VNS_ATTR_4_ORIG as CFI_VNS_ATTR_4_ORIG,
	 ACTION_TYPE_ERR_MSG as ACTION_TYPE_ERR_MSG,
	 NOTIONAL_2 as NOTIONAL_2,
	 CLEARING_MEMBER_LCH_CODE_PAR31 as CLEARING_MEMBER_LCH_CODE_PAR31
From DSR_EXP_FORMAT_ISINOut as DSR_EXP_FORMAT_ISINOut
LEFT JOIN (
SELECT DATE_VALUE, VARIABLE_NAME FROM (  SELECT DATE_VALUE, VARIABLE_NAME,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT DATE_VALUE, VARIABLE_NAME,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME ORDER BY VARIABLE_NAME NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    APPLICATION_VARIABLES )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.VARIABLE_NAME = 'EMIR_L3_GO_LIVE_DATE'
LEFT JOIN (
SELECT DATE_VALUE, VARIABLE_NAME FROM (  SELECT DATE_VALUE, VARIABLE_NAME,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT DATE_VALUE, VARIABLE_NAME,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME ORDER BY VARIABLE_NAME NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    APPLICATION_VARIABLES )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.VARIABLE_NAME = 'EMIR_MIFIDII_EFFECTIVE_DATE'
LEFT JOIN (
SELECT TOTV_INDICATOR, ISIN, TOTV_EFFECTIVE_FROM_DATE, EFFECTIVE_TO_DATE FROM (  SELECT TOTV_INDICATOR, ISIN, TOTV_EFFECTIVE_FROM_DATE, EFFECTIVE_TO_DATE,  ROW_NUMBER() OVER (PARTITION BY ISIN, TOTV_EFFECTIVE_FROM_DATE, EFFECTIVE_TO_DATE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT TOTV_INDICATOR, ISIN, TOTV_EFFECTIVE_FROM_DATE, EFFECTIVE_TO_DATE,  ROW_NUMBER() OVER (PARTITION BY ISIN, TOTV_EFFECTIVE_FROM_DATE, EFFECTIVE_TO_DATE ORDER BY ISIN, TOTV_EFFECTIVE_FROM_DATE, EFFECTIVE_TO_DATE NULLS LAST) AS rnk_fst   FROM ( SELECT    null as TOTV_INDICATOR,    SECURITY_IDENTIFIERS_TOTV_DIM.ISIN as ISIN,    SECURITY_IDENTIFIERS_TOTV_DIM.EFFECTIVE_FROM_DATE as TOTV_EFFECTIVE_FROM_DATE,    NVL(SECURITY_IDENTIFIERS_TOTV_DIM.EFFECTIVE_TO_DATE,TO_DATE('31-DEC-2099','DD-MON-YYYY')) as EFFECTIVE_TO_DATE FROM    SECURITY_IDENTIFIERS_TOTV_DIM )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.ISIN = ISIN AND dsf_3.TOTV_EFFECTIVE_FROM_DATE <= O_CLEARING_TIMESTAMP_FIN_ISIN AND dsf_3.EFFECTIVE_TO_DATE >= O_CLEARING_TIMESTAMP_FIN_ISIN
),

