	 LCH_PRODUCT_TYPE_TRA as LCH_PRODUCT_TYPE_TRA,
	 PRODUCT_TYPE_TRA as PRODUCT_TYPE_TRA,
	 FLOATING_RATE_LEG1_INDEX_NAME_FULL as FLOATING_RATE_LEG1_INDEX_NAME_FULL,
	 FLOATING_RATE_LEG2_INDEX_NAME_FULL as FLOATING_RATE_LEG2_INDEX_NAME_FULL,
	 BATCH_DETAILS_ID as BATCH_DETAILS_ID,
	 BATCH_ID as BATCH_ID,
	 o_PRODUCT_NAME3 as o_PRODUCT_NAME3,
	 V_ROWCOUNT as O_ROWCOUNT,
	 dsCurrentTimestamp ( ) as O_REC_TIMESTAMP,
	 ( CASE WHEN O_ERROR_IND = 'N' THEN 0 ELSE 1 END ) as O_MD_ERROR_IND,
	 1 as O_MD_ACTIVE_IND,
	 ( CASE WHEN dsf_1.NUMBER_VALUE IS NULL THEN 100000 ELSE dsf_1.NUMBER_VALUE END ) as v_PAGE_LIMIT,
	 TO_DATE ( '{{ var("BATCH_BUSINESS_DATE") }}',
	 'YYYYMMDD' ) as O_BUSINESS_DATE,
	 TO_TIMESTAMP ( '{{ var("BATCH_START_DATE") }}',
	 'DD-Mon-YYYY HH24:MI:SS' ) as CREATED_TS,
	 DECODE ( TRUE,
	 V_ROWCOUNT >= v_PAGE_LIMIT,
	 2,
	 V_ROWCOUNT + 1 ) as V_ROWCOUNT,
	 DECODE ( TRUE,
	 V_ROWCOUNT >= v_PAGE_LIMIT,
	 V_FILECOUNT + 1,
	 V_FILECOUNT ) as V_FILECOUNT,
	 TO_VARCHAR ( CURRENT_TIMESTAMP ( ),
	 'YYYYMMDDHH24MISS' ) as V_FILE_SYSDATETIME,
	 ( CASE WHEN O_ERROR_IND = 'N' THEN '{{ var("ENTITY") }}' || '_' || '{{ var("SERVICE") }}' || '_TRADES_' || '{{ var("BATCH_BUSINESS_DATE") }}' || '_' || V_FILE_SYSDATETIME || '_' || TO_VARCHAR ( V_FILECOUNT + 1 ) || '.dat' ELSE NULL END ) as FileName,
	 TO_NUMBER ( TO_VARCHAR ( CURRENT_TIMESTAMP ( ),
	 'YYYY-MM-DD' ) ) as BST_YEAR,
	 dsf_2.BST_APPLICABLE as BST_FLAG,
	 DATEADD ( '' hh24 '',
	 ),
	 CURRENT_TIMESTAMP ) as V_SESSSTARTTIME,
	 ( CASE WHEN BST_FLAG = 'Y' THEN TO_VARCHAR ( V_SESSSTARTTIME,
	 'YYYY-MM-DD' ) || 'T' || TO_VARCHAR ( V_SESSSTARTTIME,
	 'hh24:mi:ss' ) || 'Z' ELSE TO_VARCHAR ( CURRENT_TIMESTAMP ( ),
	 'YYYY-MM-DD' ) || 'T' || TO_VARCHAR ( CURRENT_TIMESTAMP ( ),
	 'hh24:mi:ss' ) || 'Z' END ) as REPORTING_TIMESTAMP,
	 TO_VARCHAR ( ( CASE WHEN NOTIONAL_2 IS NULL THEN NULL ELSE TO_VARCHAR ( SUBSTRING ( NOTIONAL_2,
	 1,
	 REGEXP_INSTR ( NOTIONAL_2,
	 '.' ) -1 ) ) || ( CASE WHEN REGEXP_INSTR ( NOTIONAL_2,
	 '.' ) > 0 THEN TO_VARCHAR ( SUBSTRING ( SUBSTRING ( NOTIONAL_2,
	 REGEXP_INSTR ( NOTIONAL_2,
	 '.' ) ),
	 1,
	 21 - LENGTH ( SUBSTRING ( ABS ( NOTIONAL_2 ),
	 1,
	 REGEXP_INSTR ( ABS ( NOTIONAL_2 ),
	 '.' ) -1 ) ) ) ) ELSE null END ) END ) ) as o_NOTIONAL_2,
	 CLEARING_MEMBER_LCH_CODE_PAR31 as CLEARING_MEMBER_LCH_CODE_PAR31
From SRT_UTI_EXETIM_ACTION_TYPOut as SRT_UTI_EXETIM_ACTION_TYPOut
LEFT JOIN (
SELECT NUMBER_VALUE, STRING_VALUE FROM (  SELECT NUMBER_VALUE, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT NUMBER_VALUE, STRING_VALUE,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE ORDER BY STRING_VALUE NULLS LAST) AS rnk_fst   FROM ( SELECT    APPLICATION_VARIABLES.NUMBER_VALUE as NUMBER_VALUE,    APPLICATION_VARIABLES.STRING_VALUE as STRING_VALUE FROM    APPLICATION_VARIABLES WHERE    VARIABLE_NAME= 'PAGINATION_LIMITS' AND   ACTIVE_Y_N= 'Y' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.STRING_VALUE = 'UV'
LEFT JOIN (
SELECT BST_APPLICABLE, YEAR, FROM_DT, TO_DT FROM (  SELECT BST_APPLICABLE, YEAR, FROM_DT, TO_DT,  ROW_NUMBER() OVER (PARTITION BY YEAR, FROM_DT, TO_DT ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT BST_APPLICABLE, YEAR, FROM_DT, TO_DT,  ROW_NUMBER() OVER (PARTITION BY YEAR, FROM_DT, TO_DT ORDER BY YEAR, FROM_DT, TO_DT NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    BST_DATE_RANGE )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.YEAR = BST_YEAR AND dsf_2.FROM_DT <= SESSSTARTTIME AND dsf_2.TO_DT >= SESSSTARTTIME
),

SRT_AGG_FILE_GEN_DTLS_DIMOut as (
