From EXP_FORMAT_POST_DVOut1 as EXP_FORMAT_POST_DVOut1 Order By FileName ASC),

DSR_AGG_FILE_GEN_DTLS_DIMOut as (
	/* transType: "Expression" */
Select 
	SRT_AGG_FILE_GEN_DTLS_DIMOut.FileName as FileName,
	 SRT_AGG_FILE_GEN_DTLS_DIMOut.O_BATCH_ID as BATCH_ID,
	 SRT_AGG_FILE_GEN_DTLS_DIMOut.O_REC_TIMESTAMP as I_REC_TIMESTAMP,
	 SRT_AGG_FILE_GEN_DTLS_DIMOut.O_APPLICATION_ID as APPLICATION_ID,
	 SRT_AGG_FILE_GEN_DTLS_DIMOut.O_APPLICATION_NAME as APPLICATION_NAME
From SRT_AGG_FILE_GEN_DTLS_DIMOut as SRT_AGG_FILE_GEN_DTLS_DIMOut),

AGG_FILE_GEN_DTLS_DIM_Out as (
	/* transType: "Aggregator" */
 
 select 
	FileName as FileName,
	 COUNT ( 1 ) as O_MAX_COUNT,
	 MIN ( I_REC_TIMESTAMP ) as O_MIN_REC_TIMESTAMP,
	 MAX ( I_REC_TIMESTAMP ) as O_MAX_REC_TIMESTAMP
 from DSR_AGG_FILE_GEN_DTLS_DIMOut
 group by FileName
),
AGG_FILE_GEN_DTLS_DIM_NonGroupBy as (
 select 
  	FileName,
	 BATCH_ID,
	 APPLICATION_ID,
	 APPLICATION_NAME
 from (
  select 
   	FileName,
	 BATCH_ID,
	 APPLICATION_ID,
	 APPLICATION_NAME,
   ROW_NUMBER() OVER (
    PARTITION BY FileName
    ORDER BY FileName
   ) as rnk_lst
  from DSR_AGG_FILE_GEN_DTLS_DIMOut
 ) t
 where rnk_lst = 1
),
AGG_FILE_GEN_DTLS_DIMOut as (
 select 
	dsf_1.FileName,
	 dsf_1.O_MAX_COUNT,
	 dsf_1.O_MIN_REC_TIMESTAMP,
	 dsf_1.O_MAX_REC_TIMESTAMP,
	 dsf_2.BATCH_ID,
	 dsf_2.APPLICATION_ID,
	 dsf_2.APPLICATION_NAME
 from AGG_FILE_GEN_DTLS_DIM_Out dsf_1
 inner join AGG_FILE_GEN_DTLS_DIM_NonGroupBy dsf_2 on dsf_1.FileName = dsf_2.FileName
)
),

LKP_BATCH_MASTEROut as (
	/* transType: "Lookup Procedure" */
Select 
	BATCH_ID as BATCH_ID,
	 BATCH_FEED_INFO as BATCH_FEED_INFO,
