EXP_FILE_GEN_DTLS_DIMOut as (
	/* transType: "Expression" */
Select 
	FileName as FileName,
	 BATCH_ID as BATCH_ID,
	 '{{ var("REPORT_ID") }}' as REPORT_ID,
	 '{{ var("REPORT_NAME") }}' as DESCRIPTION,
	 dsCurrentTimestamp ( ) as CREATION_DATETIME,
	 '{{ var("ENTITY") }}' || '_' || '{{ var("SERVICE") }}' as SENDER,
	 'UnaVista' as RECIPIENT,
	 FILE_GEN_START_DATETIME as FILE_GEN_START_DATETIME,
	 FILE_GEN_END_DATETIME as FILE_GEN_END_DATETIME,
	 TOTAL_RECORDS as TOTAL_RECORDS,
	 APPLICATION_ID1 as APPLICATION_ID1,
	 APPLICATION_NAME as APPLICATION_NAME,
	 'C' as STATUS,
	 dsf_1.SPL_MODE_RUN_ID as V_SPL_MODE_RUN_ID,
	 '{{ var("BATCH_MODE") }}' as O_BATCH_MODE,
	 REMARKS as REMARKS,
	 ( CASE WHEN in_AUTO_REPORT_SUBMISSION_FLG = 'Y' THEN REMARKS ELSE NULL END ) as V_COMMENTS_NORMAL,
	 DECODE ( '{{ var("EMIR_TR_EXTRACTION_MODE") }}',
	 'DMP',
	 'EMIR_TR_EXTRACTION_MODE = DMP~SPL_MODE_RUN_ID=' || V_SPL_MODE_RUN_ID || '~' || REMARKS,
	 'ERROR',
	 'EMIR_TR_EXTRACTION_MODE = ERROR~SPL_MODE_RUN_ID=' || V_SPL_MODE_RUN_ID || '~' || REMARKS,
	 'DELTA',
	 'EMIR_TR_EXTRACTION_MODE = DELTA~SPL_MODE_RUN_ID=' || V_SPL_MODE_RUN_ID || '~' || REMARKS,
	 V_COMMENTS_NORMAL ) as V_COMMENTS_ASG_Y,
	 DECODE ( '{{ var("EMIR_TR_EXTRACTION_MODE") }}',
	 'DMP',
	 'EMIR_TR_EXTRACTION_MODE = DMP~SPL_MODE_RUN_ID=' || V_SPL_MODE_RUN_ID,
	 'ERROR',
	 'EMIR_TR_EXTRACTION_MODE = ERROR~SPL_MODE_RUN_ID=' || V_SPL_MODE_RUN_ID,
	 'DELTA',
	 'EMIR_TR_EXTRACTION_MODE = DELTA~SPL_MODE_RUN_ID=' || V_SPL_MODE_RUN_ID,
	 NULL ) as V_COMMENTS_ASG_N,
	 ( CASE WHEN in_AUTO_REPORT_SUBMISSION_FLG = 'Y' THEN V_COMMENTS_ASG_Y ELSE V_COMMENTS_ASG_N END ) as O_COMMENTS,
	 dsf_2.STRING_VALUE5 as v_LKP_APP_VAR_AUTO_RPT_SUB_FLG,
	 ( CASE WHEN in_AUTO_REPORT_SUBMISSION_FLG = 'Y' THEN 'Y' ELSE v_LKP_APP_VAR_AUTO_RPT_SUB_FLG END ) as AUTO_REPORT_SUBMISSION_FLG
From dsJoiner_EXP_FILE_GEN_DTLS_DIM0Out as dsJoiner_EXP_FILE_GEN_DTLS_DIM0Out
LEFT JOIN (
SELECT SPL_MODE_RUN_ID, SERVICE FROM (  SELECT SPL_MODE_RUN_ID, SERVICE,  ROW_NUMBER() OVER (PARTITION BY SERVICE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT SPL_MODE_RUN_ID, SERVICE,  ROW_NUMBER() OVER (PARTITION BY SERVICE ORDER BY SERVICE NULLS LAST) AS rnk_fst   FROM ( SELECT    * FROM    RR_EMIR_TR_EXTRACTION_MODE )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.SERVICE = '{{ var("SERVICE") }}'
LEFT JOIN (
SELECT STRING_VALUE5, STRING_VALUE3, STRING_VALUE4 FROM (  SELECT STRING_VALUE5, STRING_VALUE3, STRING_VALUE4,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE3, STRING_VALUE4 ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE5, STRING_VALUE3, STRING_VALUE4,  ROW_NUMBER() OVER (PARTITION BY STRING_VALUE3, STRING_VALUE4 ORDER BY STRING_VALUE3, STRING_VALUE4 NULLS LAST) AS rnk_fst   FROM ( SELECT    APPLICATION_VARIABLES.STRING_VALUE5 as STRING_VALUE5,    APPLICATION_VARIABLES.STRING_VALUE3 as STRING_VALUE3,    APPLICATION_VARIABLES.STRING_VALUE4 as STRING_VALUE4 FROM    APPLICATION_VARIABLES WHERE    APPLICATION_VARIABLES.VARIABLE_NAME= 'DATA_CONTROL_FRAMEWORK' AND   APPLICATION_VARIABLES.STRING_VALUE= 'REPORT_LEVEL_AUTO_SUBMISSION' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.STRING_VALUE3 = in_BATCH_FEED_INFO AND dsf_2.STRING_VALUE4 = '{{ var("REPORT_ID") }}'
),

